const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:36,840", "arabic": "إِنِّي لَمْ أَجِدْ مَنْ يَعْزِمُ عَلَى شِرَائِهِ، كُلُّ مَنْ تَعْرِفُهُمْ وَمَنْ تَعْرِفُ أَنْتَ غَيْرُ الْبُؤَسَاءِ وَالْفُقَرَاءِ الْمُعْدَمِينَ", "segs": [{"ar": "إِنِّي لَمْ أَجِدْ مَنْ يَعْزِمُ عَلَى شِرَائِهِ", "uz": "uni sotib olishga qat'iy niyat qilgan kimsani topmadim"}, {"ar": "كُلُّ مَنْ تَعْرِفُهُمْ وَمَنْ تَعْرِفُ أَنْتَ غَيْرُ الْبُؤَسَاءِ وَالْفُقَرَاءِ الْمُعْدَمِينَ", "uz": "sen taniganlaring va bilganlaring esa baxtsiz va qashshoq kambag'allardan boshqa hech kim emas"}], "full_uz": "Uni sotib olishga qat'iy niyat qilgan kimsani topmadim — sen taniganlaring va bilganlaring esa baxtsiz va qashshoq kambag'allardan boshqa hech kim emas.", "note": null},
  {"num": 4, "time": "00:00:36,840 --> 00:00:39,000", "arabic": "هَلْ تَظُنُّ هَؤُلَاءِ يَشْتَرُونَ جَارِيَةً؟", "segs": null, "full_uz": "Sizningcha, ular cho'ri sotib olisharmi?", "note": null},
  {"num": 5, "time": "00:00:39,579 --> 00:00:43,859", "arabic": "عَلَيْكَ أَنْ تَطْرُقَ أَبْوَابَ السَّادَةِ وَالتُّجَّارِ وَأَهْلِ الْيَسَارِ أَيُّهَا الذَّكِيُّ", "segs": null, "full_uz": "Boy-badavlat, savdogar va farovon kishilarning eshigini qoqishing kerak, ey aqlli.", "note": null},
  {"num": 6, "time": "00:00:43,859 --> 00:00:49,920", "arabic": "حَسَنًا مِنَ الْغَدِ صَبَاحًا سَأَعُودُ إِلَى السُّوقِ ثَانِيَةً لَعَلِّي أَجِدُ مَنْ يَشْتَرِي تِلْكَ الْجَارِيَةَ", "segs": null, "full_uz": "Xo'p, ertaga tongdan yana bozorga qaytaman, shoyad o'sha cho'rini sotib oladigan kimsani topsam.", "note": null},
  {"num": 7, "time": "00:00:49,920 --> 00:00:53,719", "arabic": "سَتَفْعَلُ، وَإِنْ عُدْتَ خَائِبًا سَتَرَى مِنِّي مَا تَكْرَهُ", "segs": null, "full_uz": "Shunday qilasan, va agar bo'sh qaytsang, mendan yoqtirmagan narsalaringni ko'rasan.", "note": null},
  {"num": 8, "time": "00:01:00,000 --> 00:01:13,640", "arabic": "لَنْ أَكُونَ جَارِيَةً، لَنْ أَكُونَ", "segs": null, "full_uz": "Cho'ri bo'lmayman, bo'lmayman.", "note": null},
  {"num": 10, "time": "00:01:13,640 --> 00:01:27,640", "arabic": "لَقَدْ عَزَمْتُ عَلَى اللَّحَاقِ بِحَلْقَةِ الْقَاضِي أَبِي يُوسُفَ، صَاحِبِ الْإِمَامِ أَبِي حَنِيفَةَ النُّعْمَانِ", "segs": null, "full_uz": "Qozi Abu Yusufning — imom Abu Hanifa an-Nu'monning shogirdi — darsiga qo'shilishga qaror qildim.", "note": null},
  {"num": 12, "time": "00:01:27,640 --> 00:01:35,519", "arabic": "حَسُنَ صَنِيعُكَ وَطَابَتْ خَيْرَتُكَ يَا مُحَمَّدُ، كُنْتُ عَلَى ثِقَةٍ مِنْ إِعْجَابِكَ بِهِ وَاحْتِرَامِكَ لَهُ", "segs": [{"ar": "حَسُنَ صَنِيعُكَ وَطَابَتْ خَيْرَتُكَ يَا مُحَمَّدُ", "uz": "ishing yaxshi, tanlaganing to'g'ri, Muhammad"}, {"ar": "كُنْتُ عَلَى ثِقَةٍ مِنْ إِعْجَابِكَ بِهِ وَاحْتِرَامِكَ لَهُ", "uz": "unga hayrating va hurmating borligiga aminman edim"}], "full_uz": "Ishing yaxshi, tanlaganing to'g'ri, Muhammad — unga hayrating va hurmating borligiga aminman edim.", "note": null},
  {"num": 14, "time": "00:01:35,519 --> 00:01:48,460", "arabic": "وَمَنْ لَا يُعْجِبُهُ أَبُو يُوسُفَ يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ حَبِيبٍ، صَاحِبُ كِتَابِ الْخَرَاجِ وَتِلْمِيذُ الْإِمَامِ أَبِي حَنِيفَةَ النُّعْمَانِ وَحَامِلُ عِلْمِهِ", "segs": [{"ar": "وَمَنْ لَا يُعْجِبُهُ أَبُو يُوسُفَ يَعْقُوبُ بْنُ إِبْرَاهِيمَ بْنِ حَبِيبٍ", "uz": "Abu Yusuf Ya'qub ibn Ibrohim ibn Habibdan kim hayratlanmasin"}, {"ar": "صَاحِبُ كِتَابِ الْخَرَاجِ وَتِلْمِيذُ الْإِمَامِ أَبِي حَنِيفَةَ النُّعْمَانِ وَحَامِلُ عِلْمِهِ", "uz": "«al-Xaroj» kitobining muallifi, imom Abu Hanifaning shogirdi va uning ilmini davom ettiruvchisi"}], "full_uz": "Abu Yusuf Ya'qub ibn Ibrohim ibn Habibdan kim hayratlanmasin — «al-Xaroj» kitobining muallifi, imom Abu Hanifaning shogirdi va uning ilmini davom ettiruvchisi.", "note": null},
  {"num": 17, "time": "00:01:48,460 --> 00:01:54,019", "arabic": "إِذَنْ مَتَى تَرَى أَنْ نَلْتَحِقَ بِهِ يَا ابْنَ حَنْبَلٍ؟", "segs": null, "full_uz": "Unda, sizningcha, unga qachon qo'shilamiz, Ibn Hanbal?", "note": null},
  {"num": 18, "time": "00:01:54,019 --> 00:01:56,079", "arabic": "تَقُولُ نَلْتَحِقُ؟", "segs": null, "full_uz": "«Qo'shilamiz» deysizmi?", "note": null},
  {"num": 19, "time": "00:01:56,079 --> 00:01:57,180", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 20, "time": "00:01:57,180 --> 00:02:00,340", "arabic": "تَسُرُّنِي مُرَافَقَتُكَ وَالسَّيْرُ فِي صُحْبَتِكَ", "segs": null, "full_uz": "Senga hamroh bo'lish va birga yurish meni xursand qiladi.", "note": null},
  {"num": 21, "time": "00:02:00,340 --> 00:02:05,900", "arabic": "أَخْشَى أَنَّنِي لَا أَسْتَطِيعُ ذَلِكَ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Qo'rqamanki, bunga qodir emasman, Ibn Nuh.", "note": null},
  {"num": 22, "time": "00:02:05,900 --> 00:02:13,480", "arabic": "وَاللَّهِ أَنَا فِي حَيْرَةٍ مِنْ أَمْرِكَ يَا ابْنَ حَنْبَلٍ، أَنْتَ وَلُوعٌ بِعِلْمِ الرَّجُلِ وَتَكْسَلُ عَنِ الِالْتِحَاقِ بِحَلْقَتِهِ", "segs": [{"ar": "وَاللَّهِ أَنَا فِي حَيْرَةٍ مِنْ أَمْرِكَ يَا ابْنَ حَنْبَلٍ", "uz": "vallohi, ishingdan hayronman, Ibn Hanbal"}, {"ar": "أَنْتَ وَلُوعٌ بِعِلْمِ الرَّجُلِ وَتَكْسَلُ عَنِ الِالْتِحَاقِ بِحَلْقَتِهِ", "uz": "u kishining ilmiga o'ch bo'lasan-u, uning darsiga qo'shilishga erinasan"}], "full_uz": "Vallohi, ishingdan hayronman, Ibn Hanbal — u kishining ilmiga o'ch bo'lasan-u, uning darsiga qo'shilishga erinasan.", "note": null},
  {"num": 24, "time": "00:02:13,480 --> 00:02:18,159", "arabic": "اَلْأَمْرُ لَيْسَ كَمَا فَهِمْتَ يَا مُحَمَّدُ، أَخْشَى أَنَّهُ فَوْقَ طَاقَتِي", "segs": null, "full_uz": "Ish sen tushungandek emas, Muhammad, qo'rqamanki, u mening qo'limdan kelmaydi.", "note": null},
  {"num": 26, "time": "00:02:18,159 --> 00:02:21,500", "arabic": "مَا قَصَدْتُهُ أَنَّهُ قَدْ يَضِيقُ بِي الْوَقْتُ", "segs": null, "full_uz": "Nazarda tutganim — vaqtim yetmasligi mumkin.", "note": null},
  {"num": 27, "time": "00:02:21,500 --> 00:02:29,379", "arabic": "تَعْرِفُ وَأَعْرِفُ أَنَّ مَوَاعِيدَ أَبِي يُوسُفَ أَحَدُّ مِنَ السَّيْفِ، وَلَنْ يَسُرَّهُ أَنْ يَرَى طَالِبَ عِلْمٍ يَتَأَخَّرُ عَلَى حَلْقَةِ دَرْسِهِ", "segs": [{"ar": "تَعْرِفُ وَأَعْرِفُ أَنَّ مَوَاعِيدَ أَبِي يُوسُفَ أَحَدُّ مِنَ السَّيْفِ", "uz": "sen ham, men ham bilamiz — Abu Yusufning vaqt intizomi qilichdan ham o'tkirroq"}, {"ar": "وَلَنْ يَسُرَّهُ أَنْ يَرَى طَالِبَ عِلْمٍ يَتَأَخَّرُ عَلَى حَلْقَةِ دَرْسِهِ", "uz": "va dars vaqtiga kechikkan ilm talabgorini ko'rish uni xursand qilmaydi"}], "full_uz": "Sen ham, men ham bilamiz — Abu Yusufning vaqt intizomi qilichdan ham o'tkirroq, va dars vaqtiga kechikkan ilm talabgorini ko'rish uni xursand qilmaydi.", "note": null},
  {"num": 29, "time": "00:02:29,379 --> 00:02:33,219", "arabic": "وَلَنْ أَرْضَى ذَلِكَ لِنَفْسِي وَلَا أُحِبُّ أَنْ أَسْمَعَ مِنْهُ تَقْرِيعًا", "segs": null, "full_uz": "Buni o'zimga ravo ko'rmayman va undan tanbeh eshitishni istamayman.", "note": null},
  {"num": 30, "time": "00:02:33,219 --> 00:02:38,340", "arabic": "كَمَا أَنَّ وَقْتِي لَيْسَ مِلْكِي وَخَاصَّةً بَعْدَ أَنْ تَرَكْتُ الْعَمَلَ فِي بَيْتِ الْحِكْمَةِ", "segs": null, "full_uz": "Bundan tashqari, vaqtim endi o'zimniki emas, ayniqsa Baytul-Hikmadagi ishimni tashlab qo'yganimdan keyin.", "note": null},
  {"num": 31, "time": "00:02:38,340 --> 00:02:41,739", "arabic": "أَلَمْ تَقُلْ لِي أَنَّكَ سَتَتَفَرَّغُ لِطَلَبِ الْعِلْمِ؟", "segs": null, "full_uz": "Menga ilm izlashga bag'ishlanaman demaganmiding?", "note": null},
  {"num": 32, "time": "00:02:41,739 --> 00:02:45,000", "arabic": "فَلِمَ الْخَشْيَةُ مِنَ التَّأْخِيرِ إِذَنْ؟", "segs": null, "full_uz": "Unda, kechikishdan qo'rqish nimaga kerak?", "note": null},
  {"num": 33, "time": "00:02:45,000 --> 00:02:48,039", "arabic": "لَا أَدْرِي يَا مُحَمَّدُ، إِنَّنِي مُتَهَيِّبٌ قَلِيلًا", "segs": null, "full_uz": "Bilmayman, Muhammad, biroz cho'chiyapman.", "note": null},
  {"num": 34, "time": "00:02:48,039 --> 00:02:52,340", "arabic": "مُتَهَيِّبٌ قَلِيلًا؟ مِثْلُكَ لَا يَقُولُ هَذَا يَا أَحْمَدُ", "segs": null, "full_uz": "Biroz cho'chiyapmanmi? Sendaqasi bunday demaydi, Ahmad.", "note": null},
  {"num": 35, "time": "00:02:55,039 --> 00:02:57,359", "arabic": "وَلِمَ التَّهَيُّبُ يَا وَلَدِي؟", "segs": null, "full_uz": "Nega cho'chiyapsan, o'g'lim?", "note": null},
  {"num": 36, "time": "00:02:57,359 --> 00:03:05,819", "arabic": "اَلِالْتِحَاقُ بِحَلْقَةِ الشَّيْخِ أَبِي يُوسُفَ فُرْصَةٌ ثَمِينَةٌ فَاغْتَنِمْهَا، فَمَا فِي يَدِكَ الْيَوْمَ قَدْ لَا تُدْرِكُهُ غَدًا", "segs": [{"ar": "اَلِالْتِحَاقُ بِحَلْقَةِ الشَّيْخِ أَبِي يُوسُفَ فُرْصَةٌ ثَمِينَةٌ فَاغْتَنِمْهَا", "uz": "shayx Abu Yusuf halqasiga qo'shilish qimmatli fursat, uni g'animat bil"}, {"ar": "فَمَا فِي يَدِكَ الْيَوْمَ قَدْ لَا تُدْرِكُهُ غَدًا", "uz": "chunki bugun qo'lingdagi narsaga ertaga yetolmasliging mumkin"}], "full_uz": "Shayx Abu Yusuf halqasiga qo'shilish qimmatli fursat, uni g'animat bil — chunki bugun qo'lingdagi narsaga ertaga yetolmasliging mumkin.", "note": null},
  {"num": 38, "time": "00:03:05,819 --> 00:03:10,340", "arabic": "وَالْعُلَمَاءُ سُرُجٌ يَا وَلَدِي، لَا نَدْرِي مَتَى تَنْطَفِئُ", "segs": null, "full_uz": "Olimlar chiroqdek, o'g'lim, qachon o'chishini bilmaymiz.", "note": "Olimlarni «chiroq» (سُرُجٌ) ga qiyoslash — ularning ilmi bilan atrofni yoritishi, ammo umri (chiroq nuridek) cheklanganini bildiruvchi majoziy ibora."},
  {"num": 40, "time": "00:03:10,340 --> 00:03:16,079", "arabic": "سَيُرَافِقُكَ يَا ابْنَ نُوحٍ، وَلَكِنْ يَا أُمِّي الْقَاضِي أَبُو يُوسُفَ أَحْزَمُ مِنْ سِنَانٍ", "segs": null, "full_uz": "Ibn Nuh senga hamroh bo'ladi. — Lekin, onajon, qozi Abu Yusuf nayzadan ham qat'iyroq.", "note": "«أَحْزَمُ مِنْ سِنَانٍ» — «nayza uchidan ham qat'iyroq», ya'ni juda qattiqqo'l va intizomli ma'nosidagi ibora."},
  {"num": 42, "time": "00:03:16,079 --> 00:03:17,479", "arabic": "وَأَخْشَى أَنَّهُ لَنْ يَرْضَى", "segs": null, "full_uz": "Va qo'rqamanki, u mendan rozi bo'lmaydi.", "note": null},
  {"num": 43, "time": "00:03:17,479 --> 00:03:22,239", "arabic": "مَنْ أَرَاكَ هَيَّابًا هَكَذَا يَا وَلَدِي؟ دَعْكَ مِنْ هَذِهِ الْأَعْذَارِ الْوَاهِيَةِ", "segs": null, "full_uz": "Seni bunday qo'rqoq qilib qo'ygan kim, o'g'lim? Bu bo'sh bahonalarni qo'y.", "note": null},
  {"num": 45, "time": "00:03:22,240 --> 00:03:29,219", "arabic": "سَتَذْهَبُ مَعَ مُحَمَّدٍ وَلَنْ تَتَخَلَّفَ عَنْ حَلْقَةِ الشَّيْخِ أَبِي يُوسُفَ مَهْمَا كَانَتِ الْأَسْبَابُ", "segs": null, "full_uz": "Muhammad bilan borasan va qanday sabab bo'lishidan qat'i nazar, shayx Abu Yusuf halqasidan qolmaysan.", "note": null},
  {"num": 46, "time": "00:03:29,219 --> 00:03:33,580", "arabic": "وَلَكِنْ يَا أُمِّي", "segs": null, "full_uz": "Lekin, onajon...", "note": null},
  {"num": 47, "time": "00:03:33,580 --> 00:03:35,280", "arabic": "قُضِيَ الْأَمْرُ يَا أَحْمَدُ", "segs": null, "full_uz": "Ish hal bo'ldi, Ahmad.", "note": null},
  {"num": 48, "time": "00:03:35,280 --> 00:03:41,840", "arabic": "حَسَنًا، طَوْعَ أَمْرِكِ يَا أُمِّي", "segs": null, "full_uz": "Xo'p, aytganingdek bo'lsin, onajon.", "note": null},
  {"num": 49, "time": "00:03:41,840 --> 00:03:43,520", "arabic": "شُكْرًا يَا خَالَتِي", "segs": null, "full_uz": "Rahmat, xolajon.", "note": null},
  {"num": 50, "time": "00:03:43,520 --> 00:03:49,580", "arabic": "اَلْأَمْرُ مَا قَضَتْ بِهِ خَالَتِي أُمُّ أَحْمَدَ، وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ", "segs": null, "full_uz": "Ish xolam Umm Ahmad hal qilgandek bo'ladi. Va ularga rahmdillik bilan kamtarlik qanotini yoy.", "note": "«وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ» — bu Qur'oni karimning Isro surasi, 24-oyatidan bir bo'lak, ota-onaga mehr va kamtarlik bilan muomala qilishga chaqiruvchi mashhur oyat."},
  {"num": 52, "time": "00:04:02,760 --> 00:04:05,200", "arabic": "قَدْ نَضَبَ زَيْتُ السِّرَاجِ، وَلَا أَدْرِي إِلَى أَيْنَ ذَهَبَ ذَلِكَ فَرَجُ", "segs": null, "full_uz": "Chiroqning moyi tugadi, va o'sha Faraj qayerga ketganini bilmayman.", "note": null},
  {"num": 54, "time": "00:04:05,200 --> 00:04:09,080", "arabic": "لَقَدْ خَرَجَ مُنْذُ الصَّبَاحِ وَلَمْ يَعُدْ", "segs": null, "full_uz": "Ertalabdan chiqib ketgan, hali qaytmadi.", "note": null},
  {"num": 55, "time": "00:04:09,080 --> 00:04:15,380", "arabic": "وَهُوَ يَعْلَمُ لَيْسَ لَدَيْنَا كِسْرَةُ خُبْزٍ، يَكَادُ الْجُوعُ يَفْتِكُ بِهِ", "segs": null, "full_uz": "Bizda bir bo'lak non ham yo'qligini biladi-yu, ochlik uni yeb qo'yayozibdi.", "note": null},
  {"num": 57, "time": "00:04:15,380 --> 00:04:18,840", "arabic": "وَذَلِكَ الْأَحْمَقُ مُتَغَيِّبٌ مُنْذُ الصَّبَاحِ الْبَاكِرِ", "segs": null, "full_uz": "O'sha ahmoq esa erta tongdan g'oyib.", "note": null},
  {"num": 58, "time": "00:04:18,839 --> 00:04:22,799", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 59, "time": "00:04:22,799 --> 00:04:26,079", "arabic": "وَعَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 60, "time": "00:04:26,079 --> 00:04:30,939", "arabic": "أَيْنَ أَنْتَ مُنْذُ الصَّبَاحِ الْبَاكِرِ أَيُّهَا الْأَحْمَقُ؟", "segs": null, "full_uz": "Erta tongdan beri qayerdasan, ey ahmoq?", "note": null},
  {"num": 61, "time": "00:04:30,939 --> 00:04:32,479", "arabic": "كُنْتُ فِي قَصْرِ هَارُونَ الرَّشِيدِ", "segs": null, "full_uz": "Horun ar-Rashidning saroyida edim.", "note": null},
  {"num": 62, "time": "00:04:32,479 --> 00:04:35,899", "arabic": "كُنْتُ أَعْمَلُ فِي دُكَّانٍ وَهَذِهِ أُجْرَتِي", "segs": null, "full_uz": "Do'konda ishlab kelayapman, mana bu haqim.", "note": null},
  {"num": 63, "time": "00:04:35,899 --> 00:04:37,699", "arabic": "مَا هَذَا؟", "segs": null, "full_uz": "Bu nima?", "note": null},
  {"num": 64, "time": "00:04:42,199 --> 00:04:44,120", "arabic": "رَغِيفَانِ مِنَ الْخُبْزِ؟", "segs": null, "full_uz": "Ikki dona nonmi?", "note": null},
  {"num": 65, "time": "00:04:44,120 --> 00:04:49,000", "arabic": "أَنَا أَنْتَظِرُ رُجُوعَكَ مُنْذُ الصَّبَاحِ وَأَنْتَ تَعُودُ لِي بِرَغِيفَيْنِ مِنَ الْخُبْزِ", "segs": null, "full_uz": "Ertalabdan buyon qaytishingni kutaman-u, sen menga ikki dona non bilan qaytasan.", "note": null},
  {"num": 67, "time": "00:04:49,000 --> 00:04:53,720", "arabic": "إِنَّهُمَا رَغِيفَانِ مِنَ الْخُبْزِ وَلَكِنَّهُمَا مِنْ تَعَبِي وَكَدِّي", "segs": null, "full_uz": "Bu ikki non — mening mehnatim va toliqishimning mahsuli.", "note": null},
  {"num": 69, "time": "00:04:53,720 --> 00:04:58,600", "arabic": "إِنَّهُمَا مِنَ الْحَلَالِ لَا مِنَ الْحَرَامِ، اَلْحَلَالُ لَا يَأْتِي إِلَّا بِرَغِيفَيْنِ مِنَ الْخُبْزِ", "segs": null, "full_uz": "Ular halol, harom emas. Halol faqat ikki dona nongina keltiradi.", "note": null},
  {"num": 71, "time": "00:04:58,600 --> 00:05:04,919", "arabic": "إِنْ لَمْ يَأْتِنَا الْحَلَالُ إِلَّا بِرَغِيفِ خُبْزٍ طِيلَةَ النَّهَارِ، فَإِنَّ الْحَرَامَ لَمْ يَأْتِنَا بِشَيْءٍ طِيلَةَ الْعُمْرِ", "segs": [{"ar": "إِنْ لَمْ يَأْتِنَا الْحَلَالُ إِلَّا بِرَغِيفِ خُبْزٍ طِيلَةَ النَّهَارِ", "uz": "agar halol butun kun davomida bizga faqat bir bo'lak non keltirsa"}, {"ar": "فَإِنَّ الْحَرَامَ لَمْ يَأْتِنَا بِشَيْءٍ طِيلَةَ الْعُمْرِ", "uz": "harom esa butun umr davomida bizga hech narsa keltirmadi"}], "full_uz": "Agar halol butun kun davomida bizga faqat bir bo'lak non keltirsa, harom esa butun umr davomida bizga hech narsa keltirmadi.", "note": null},
  {"num": 74, "time": "00:05:04,919 --> 00:05:08,220", "arabic": "وَهَلْ سَنَمْضِي بَقِيَّةَ عُمْرِنَا عَلَى الْخُبْزِ لِتَتَنَعَّمِي أَنْتِ بِالْحَلَالِ", "segs": null, "full_uz": "Sen halolning ne'matidan bahramand bo'lishing uchun, biz umrimizning qolgan qismini nonga sarflaymizmi?", "note": null},
  {"num": 76, "time": "00:05:08,220 --> 00:05:13,300", "arabic": "يَا أُمِّي فَقَدْ عَاشَ أَبِي طِيلَةَ حَيَاتِي سَارِقًا وَلَمْ نَجْنِ مِنْ وَرَاءِ ذَلِكَ إِلَّا الذُّلَّ", "segs": null, "full_uz": "Onajon, otam butun umrim davomida o'g'ri bo'lib yashadi, va biz shundan faqat xo'rlikni ko'rdik.", "note": null},
  {"num": 78, "time": "00:05:13,300 --> 00:05:17,700", "arabic": "وَأَنَا لَنْ أَرْضَى بِهَذَا الذُّلِّ وَلَنْ أُوَرِّثَهُ لِأَوْلَادِي مِنْ بَعْدِي", "segs": null, "full_uz": "Men bu xo'rlikka rozi bo'lmayman va uni o'zimdan keyin farzandlarimga meros qilib qoldirmayman.", "note": null},
  {"num": 80, "time": "00:05:17,700 --> 00:05:22,559", "arabic": "اَلْيَوْمَ بَدَأْتُ بِرَغِيفَيْنِ وَلَكِنْ فِي قَابِلِ الْأَيَّامِ سَتَأْكُلِينَ الْجَوْزَ وَاللَّوْزَ", "segs": null, "full_uz": "Bugun ikki nondan boshladim, lekin keladigan kunlarda yong'oq va bodom yeysan.", "note": null},
  {"num": 82, "time": "00:05:22,559 --> 00:05:24,760", "arabic": "وَسَيَتَغَيَّرُ حَالُنَا", "segs": null, "full_uz": "Va ahvolimiz o'zgaradi.", "note": null},
  {"num": 84, "time": "00:05:24,760 --> 00:05:31,720", "arabic": "جَوْزٌ وَلَوْزٌ لِعَامِلٍ فِي دُكَّانٍ؟ عَامِلٌ فِي دُكَّانٍ هُوَ أَوَّلُ الطَّرِيقِ الَّذِي لَنْ يَطُولَ طَوِيلًا", "segs": [{"ar": "جَوْزٌ وَلَوْزٌ لِعَامِلٍ فِي دُكَّانٍ؟", "uz": "do'konda ishlovchi uchun yong'oq-bodommi?"}, {"ar": "عَامِلٌ فِي دُكَّانٍ هُوَ أَوَّلُ الطَّرِيقِ الَّذِي لَنْ يَطُولَ طَوِيلًا", "uz": "do'kondagi ishchilik — uzoq davom etmaydigan yo'lning boshlanishi xolos"}], "full_uz": "Do'konda ishlovchi uchun yong'oq-bodommi? Do'kondagi ishchilik — uzoq davom etmaydigan yo'lning boshlanishi xolos.", "note": null},
  {"num": 88, "time": "00:05:34,679 --> 00:05:39,960", "arabic": "فِي أَيِّ أَرْضٍ أَنْتَ يَا فَوْزُ وَيَا أَبِي؟", "segs": null, "full_uz": "Qaysi yerdasan, Favz, otajonim?", "note": null},
  {"num": 89, "time": "00:05:39,960 --> 00:05:42,899", "arabic": "كُفِّي يَا ابْنَتِي عَنِ الْحُزْنِ وَالْكَمَدِ", "segs": null, "full_uz": "G'am va qayg'udan qo'l tort, qizim.", "note": null},
  {"num": 90, "time": "00:05:42,899 --> 00:05:44,400", "arabic": "كَيْفَ يَا خَالَةُ كَيْفَ", "segs": null, "full_uz": "Qanday, xolajon, qanday.", "note": null},
  {"num": 91, "time": "00:05:44,400 --> 00:05:45,520", "arabic": "شَهْنَازُ", "segs": null, "full_uz": "Shahnoz.", "note": null},
  {"num": 92, "time": "00:05:45,520 --> 00:05:52,059", "arabic": "أَنَا لَا أَلُومُ عَلَيْكِ حُزْنَكِ، وَلَكِنْ إِنْ قَدَّرَ اللَّهُ لَكِ رُؤْيَةَ أَهْلِكِ سَتَرَيْنَهُمْ بِإِذْنِ اللَّهِ", "segs": null, "full_uz": "G'amingni senga ayb qilmayman, lekin agar Alloh yaqinlaringni ko'rishni taqdir qilsa, ularni Allohning izni bilan ko'rasan.", "note": null},
  {"num": 95, "time": "00:05:52,059 --> 00:05:59,320", "arabic": "وَإِنْ لَا فَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Agar bo'lmasa esa, kuch-quvvat faqat Allohning yordami bilangina bordir.", "note": null},
  {"num": 98, "time": "00:05:59,320 --> 00:06:02,239", "arabic": "هَذَا قَضَاءُ اللَّهِ عَلَيْكِ وَلَا رَادَّ لِقَضَائِهِ", "segs": null, "full_uz": "Bu — Allohning senga bo'lgan taqdiri, va Uning taqdirini hech kim qaytara olmaydi.", "note": null},
  {"num": 99, "time": "00:06:02,239 --> 00:06:09,159", "arabic": "كَيْفَ أَنْسَى لَحْمِي وَدَمِي يَا خَالَةُ، وَسِيرَتُهُمْ يَفِيضُ بِهَا صَدْرِي", "segs": null, "full_uz": "Go'shtim va qonimni qanday unutay, xolajon — ular haqidagi xotira qalbimda toshib-toshib turibdi.", "note": "«لَحْمِي وَدَمِي» — «go'shtim va qonim», ya'ni eng yaqin qarindoshlar (ota-ona, farzand) ma'nosidagi ibora."},
  {"num": 101, "time": "00:06:09,159 --> 00:06:15,559", "arabic": "وَمَا زَالَ صَدَى حَدِيثِهِمْ يَرُجُّ نَفْسِي، كَأَنِّي لَمْ أُفَارِقْهُمْ إِلَّا سَاعَةً مِنْ نَهَارٍ", "segs": null, "full_uz": "Ularning gap-so'zlari yankisi hali ham qalbimni titratadi, go'yo ulardan faqat bir soatgina ayrilgandekman.", "note": null},
  {"num": 103, "time": "00:06:15,559 --> 00:06:18,760", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilangina bor.", "note": null},
  {"num": 104, "time": "00:06:18,760 --> 00:06:23,479", "arabic": "اَللَّهُمَّ كَمَا رَدَدْتَ يُوسُفَ إِلَى يَعْقُوبَ، رُدَّهَا إِلَى أَهْلِهَا وَرُدَّ أَهْلَهَا لَهَا", "segs": null, "full_uz": "Yo Alloh, Yusufni Ya'qubga qaytargandek, uni ham o'z oilasiga qaytar va oilasini unga qaytar.", "note": "Bu — Yusuf payg'ambar va otasi Ya'qub qissasiga ishora qiluvchi duo, Qur'onda bayon etilgan mashhur voqea."},
  {"num": 106, "time": "00:06:31,239 --> 00:06:33,679", "arabic": "مَا الْمَكْتُوبُ عَلَى هَذَا الْمِشْطِ؟", "segs": null, "full_uz": "Bu taroqqa nima yozilgan?", "note": null},
  {"num": 107, "time": "00:06:33,679 --> 00:06:39,919", "arabic": "إِنَّهُ اسْمِي شَهْنَازُ، كَانَ أَبِي قَدْ أَهْدَاهُ لِي وَأَهْدَى لِأُخْتِي فَوْزَ وَاحِدًا مِثْلَهُ", "segs": null, "full_uz": "Bu — mening ismim, Shahnoz. Otam buni menga sovg'a qilgan, singlim Favzga ham xuddi shunga o'xshash birini bergan.", "note": null},
  {"num": 109, "time": "00:06:39,919 --> 00:06:42,000", "arabic": "صَنَعَهُمَا بِنَفْسِهِ", "segs": null, "full_uz": "Ikkalasini ham o'z qo'li bilan yasagan.", "note": null},
  {"num": 110, "time": "00:06:42,000 --> 00:06:45,180", "arabic": "أَدْعُو اللَّهَ أَنْ يَجْمَعَ شَمْلَكُمْ عَمَّا قَرِيبٍ", "segs": null, "full_uz": "Allohdan sizlarni tez orada birlashtirishini so'rayman.", "note": "«جَمْعُ الشَّمْلِ» — «tarqoq bo'laklarni birlashtirish», ya'ni ayrilgan yaqinlarni qayta qovushtirish ma'nosidagi ibora."},
  {"num": 111, "time": "00:06:45,180 --> 00:06:50,879", "arabic": "آمَنْتُ بِاللَّهِ يَا خَالَةُ، آمَنْتُ بِاللَّهِ", "segs": null, "full_uz": "Allohga ishondim, xolajon, Allohga ishondim.", "note": null},
  {"num": 113, "time": "00:07:02,879 --> 00:07:09,300", "arabic": "مَعَهَا كُلُّ الْحَقِّ، فَهِيَ لَمْ تَقْوَ عَلَى الْمُكُوثِ مَعِي بِذَاتِ الدَّارِ", "segs": null, "full_uz": "U haqli, chunki u men bilan bir tomda qolishga toqat qila olmadi.", "note": null},
  {"num": 115, "time": "00:07:09,300 --> 00:07:14,720", "arabic": "بَعْدَ أَنْ فُرِّقَتْ بِإِهْمَالِي بِفِلْذَةِ كَبِدِهَا", "segs": null, "full_uz": "Beparvoligim bilan uning jigarbandidan ayrilishiga sabab bo'lganimdan keyin.", "note": "«فِلْذَةُ كَبِدِهَا» — «jigarining bo'lagi», ya'ni farzand ma'nosidagi mashhur ibora."},
  {"num": 116, "time": "00:07:14,720 --> 00:07:17,320", "arabic": "وَلَكِنْ مَا الْعَمَلُ؟ مَا الْعَمَلُ؟", "segs": null, "full_uz": "Lekin nima qilish kerak? Nima qilish kerak?", "note": null},
  {"num": 117, "time": "00:07:17,320 --> 00:07:23,880", "arabic": "اَلْعَمَلُ أَنِّي فِي الْغَدِ سَأَجِدُ أَوَّلَ قَافِلَةٍ ذَاهِبَةٍ إِلَى بَغْدَادَ، وَلَنْ أَعُودَ إِلَّا بِهِمَا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Qilish kerak bo'lgan ish — ertaga Bag'dodga ketayotgan birinchi karvonni topaman, va Alloh xohlasa, faqat ular ikkovi bilan qaytaman.", "note": null},
  {"num": 119, "time": "00:07:32,720 --> 00:07:37,239", "arabic": "وَلَكِنْ مَنْ هِيَ فَتَاتُكَ يَا عَامِرُ؟ مَنْ هِيَ عَرُوسُكَ؟", "segs": null, "full_uz": "Lekin qizing kim, Omir? Kelinchaging kim?", "note": null},
  {"num": 121, "time": "00:07:37,239 --> 00:07:40,300", "arabic": "فَتَاتِي عَرُوسِي الَّتِي أَحْلُمُ بِهَا", "segs": null, "full_uz": "Mening qizim — orzu qilgan kelinchagim.", "note": null},
  {"num": 122, "time": "00:07:40,300 --> 00:07:41,540", "arabic": "يَا عَامِرُ", "segs": null, "full_uz": "Omir-a.", "note": null},
  {"num": 123, "time": "00:07:41,540 --> 00:07:45,159", "arabic": "أَحْلُمُ بِعَرُوسِي حَتَّى لَوْ لَمْ أَعْرِفْهَا", "segs": null, "full_uz": "Uni tanimasam ham, kelinchagimni orzu qilaman.", "note": null},
  {"num": 125, "time": "00:07:45,159 --> 00:07:48,860", "arabic": "سَأَقُولُ فِيهَا الشِّعْرَ، فَالشِّعْرُ كَلَامٌ كَغَيْرِهِ مِنَ الْكَلَامِ", "segs": null, "full_uz": "Uning haqida she'r aytaman — she'r ham boshqa gaplardek bir gap-da.", "note": null},
  {"num": 128, "time": "00:07:48,860 --> 00:07:51,559", "arabic": "لِمَ لَا أَقُولُ الشِّعْرَ؟", "segs": null, "full_uz": "Nega she'r aytmasligim kerak?", "note": null},
  {"num": 129, "time": "00:07:51,559 --> 00:07:53,760", "arabic": "سَأَقُولُ الشِّعْرَ", "segs": null, "full_uz": "She'r aytaman.", "note": null},
  {"num": 130, "time": "00:07:53,760 --> 00:07:56,239", "arabic": "تَعَالَيْ يَا عَرُوسِي", "segs": null, "full_uz": "Kel bu yoqqa, kelinchagim.", "note": null},
  {"num": 131, "time": "00:07:56,239 --> 00:08:24,000", "arabic": "اِسْمَعِي", "segs": null, "full_uz": "Eshit.", "note": null},
  {"num": 140, "time": "00:08:24,000 --> 00:08:26,000", "arabic": "أُمِّي", "segs": null, "full_uz": "Onajon.", "note": null},
  {"num": 141, "time": "00:08:26,000 --> 00:08:29,000", "arabic": "عَدِمَتْكَ أُمُّكَ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Onang seni yo'qotsin, Alloh xohlasa (jonim qattiq achidi senga).", "note": "«عَدِمَتْكَ أُمُّكَ» — norozilik va achchiqlanishni bildiruvchi qadimiy hazil-nafrin iborasi, jiddiy ma'noda emas."},
  {"num": 142, "time": "00:08:29,000 --> 00:08:32,000", "arabic": "لِمَاذَا لَمْ تَنَمْ حَتَّى السَّاعَةِ؟ أَلَيْسَ وَرَاءَكَ عَمَلٌ فِي الصَّبَاحِ؟", "segs": null, "full_uz": "Nega hozirgacha uxlamading? Ertalab ishing yo'qmi?", "note": null},
  {"num": 144, "time": "00:08:32,000 --> 00:08:34,000", "arabic": "لَا تَكُفُّ عَنْ حَمَاقَاتِكَ وَكَسَلِكَ", "segs": null, "full_uz": "Ahmoqliging va dangasaligingdan to'xtamaysan.", "note": null},
  {"num": 145, "time": "00:08:34,000 --> 00:08:38,000", "arabic": "يَا أَفْصَحَ مِنَ الْعَرَبِ، أَنْتَ لَا تَقْوَى عَلَى كَلَامِ الْعَوَامِّ مِنَ النَّاسِ حَتَّى تَقْرِيظَ الشِّعْرِ", "segs": null, "full_uz": "Ey arablardan ham chechan bo'lganing, sen oddiy odamlar gapini ham uddalayolmaysan, she'r maqtovini demasa ham bo'ladi.", "note": null},
  {"num": 147, "time": "00:08:38,000 --> 00:08:41,000", "arabic": "هَيَّا هَيَّا إِلَى مَرْقَدِكَ، أَخَذَتْكَ الْقَارِعَةُ", "segs": null, "full_uz": "Bo'ldi, bo'ldi, yotog'ingga bor, boshingga kulfat tushsin.", "note": "«أَخَذَتْكَ الْقَارِعَةُ» — engil, hazil ohangdagi qarg'ish-nasihat iborasi, jiddiy ma'noda emas."},
  {"num": 148, "time": "00:08:41,000 --> 00:08:45,000", "arabic": "حَسَنًا حَسَنًا يَا أُمِّي، لَقَدِ اقْتَلَعْتِ قَلْبِي", "segs": null, "full_uz": "Xo'p, xo'p, onajon, yuragimni yulib oldingiz.", "note": null},
  {"num": 149, "time": "00:08:45,000 --> 00:08:48,000", "arabic": "أَلَا تَخَفِينَ عَلَيَّ مِنَ الْفَزَعِ؟", "segs": null, "full_uz": "Meni qo'rqitib yuborishdan cho'chimaysizmi?", "note": null},
  {"num": 150, "time": "00:08:48,000 --> 00:08:51,000", "arabic": "كُنْتُ أَيْبَسُ مَكَانِي وَيُصِيبُنِي الْفَالِجُ مِنْ صُرَاخِكِ عَلَيَّ", "segs": null, "full_uz": "Ustimga baqirishingdan qotib qolar, falajlanib qolar edim.", "note": null},
  {"num": 152, "time": "00:08:51,000 --> 00:08:57,000", "arabic": "اِذْهَبْ، اذْهَبْ إِلَى فِرَاشِكَ، وَإِنْ لَمْ تَنَمْ لَتَجِدَنَّ مِنِّي مَا لَمْ تَرَ وَلَمْ تَسْمَعْ", "segs": null, "full_uz": "Bor, o'z to'shagingga bor, va agar uxlamasang, mendan ko'rmagan-eshitmaganingni ko'rasan.", "note": null},
  {"num": 155, "time": "00:09:07,000 --> 00:09:09,000", "arabic": "أُمِّي هَلْ وَجَدْتِ الْعَرُوسَ أَمْ لَا؟", "segs": null, "full_uz": "Onajon, kelinchakni topdingmi yoki yo'qmi?", "note": null},
  {"num": 156, "time": "00:09:09,000 --> 00:09:12,000", "arabic": "اَلْعَرُوسُ؟ أَهَذَا هُوَ الَّذِي يَشْغَلُ بَالَكَ؟", "segs": null, "full_uz": "Kelinchakmi? Seni shu band qilib qo'yganmi?", "note": null},
  {"num": 158, "time": "00:09:12,000 --> 00:09:14,000", "arabic": "لَا تَقْلَقْ سَنَجِدُهَا", "segs": null, "full_uz": "Xavotir olma, topamiz.", "note": null},
  {"num": 159, "time": "00:09:14,000 --> 00:09:19,000", "arabic": "كُنْتِ تَتَذَرَّعِينَ بِقِلَّةِ الْمَالِ يَا أُمِّي، وَالْآنَ نَمْلِكُ دُكَّانًا يَدُرُّ عَلَيْنَا أَرْبَاحًا كَثِيرَةً", "segs": null, "full_uz": "Onajon, pul kamligini bahona qilar eding, endi esa bizga ko'p daromad keltiradigan do'konimiz bor.", "note": null},
  {"num": 161, "time": "00:09:19,000 --> 00:09:22,000", "arabic": "مَا الَّذِي يُؤَرِّقُكَ إِلَى السَّاعَةِ؟", "segs": null, "full_uz": "Nima seni shu paytgacha uyqusiz qoldirdi?", "note": null},
  {"num": 162, "time": "00:09:22,000 --> 00:09:26,000", "arabic": "وَهَلْ تَظُنُّ الْعَرُوسَ تُبَاعُ فِي حَوَانِيتِ الْعَطَّارِينَ مِنْ أَهْلِ بَغْدَادَ؟", "segs": null, "full_uz": "Kelinchak Bag'dod attorlarining do'konida sotiladi deb o'ylaysanmi?", "note": null},
  {"num": 163, "time": "00:09:26,000 --> 00:09:28,000", "arabic": "إِنَّنِي أَبْحَثُ لَكَ عَنْ عَرُوسٍ مُنَاسِبَةٍ", "segs": null, "full_uz": "Senga munosib kelinchak izlayapman.", "note": null},
  {"num": 164, "time": "00:09:28,000 --> 00:09:31,000", "arabic": "لَا لَا يَا أُمِّي لَا، لَا أُرِيدُ أَيَّ فَتَاةٍ", "segs": null, "full_uz": "Yo'q, yo'q, onajon, yo'q, men har qanaqa qizni xohlamayman.", "note": null},
  {"num": 166, "time": "00:09:31,000 --> 00:09:34,000", "arabic": "إِنَّهَا لِوَلَدِكِ عَامِرٍ", "segs": null, "full_uz": "U o'g'ling Omirga munosib bo'lsin.", "note": null},
  {"num": 167, "time": "00:09:34,000 --> 00:09:36,000", "arabic": "إِذَنِ انْتَظِرْ وَلَا تَتَعَجَّلْ", "segs": null, "full_uz": "Unda kut, shoshilma.", "note": null},
  {"num": 168, "time": "00:09:36,000 --> 00:09:41,000", "arabic": "سَأَنْتَظِرُ يَا أُمِّي سَأَنْتَظِرُ، عَرُوسِي", "segs": null, "full_uz": "Kutaman, onajon, kutaman. Kelinchagim.", "note": null},
  {"num": 171, "time": "00:10:01,000 --> 00:10:12,000", "arabic": "أَيُّ كِتَابٍ هَذَا الَّذِي سَطَا عَلَى حَقِّ زُبَيْدَةَ مِنْكَ يَا هَارُونُ؟", "segs": null, "full_uz": "Bu qanday kitobki, sendan Zubaydaning haqqini o'g'irladi, Horun?", "note": null},
  {"num": 172, "time": "00:10:12,000 --> 00:10:15,000", "arabic": "وَمَنْ ذَا الَّذِي يَجْرُؤُ عَلَى أَخْذِي مِنْ زُبَيْدَةَ؟", "segs": null, "full_uz": "Kim meni Zubaydadan olishga jur'at etadi?", "note": null},
  {"num": 173, "time": "00:10:15,000 --> 00:10:20,000", "arabic": "إِنَّهُ كِتَابُ الْأُصُولِ فِي الْهَنْدَسَةِ وَالْعَدَدِ لِإِقْلِيدِسَ، وَقَدْ تَرْجَمَهُ عَنِ الْيُونَانِيَّةِ عَدَدٌ مِنْ عُلَمَاءِ بَيْتِ الْحِكْمَةِ", "segs": null, "full_uz": "Bu — Evklidning geometriya va sonlar asoslari kitobi, uni Baytul-Hikma olimlaridan bir nechtasi yunon tilidan tarjima qilishgan.", "note": null},
  {"num": 175, "time": "00:10:20,000 --> 00:10:23,000", "arabic": "أَرَاكَ تَكِبُّ عَلَيْهِ بِشَغَفٍ وَاهْتِمَامٍ؟", "segs": null, "full_uz": "Unga ishtiyoq va qiziqish bilan berilib ketganingni ko'ryapman-a?", "note": null},
  {"num": 176, "time": "00:10:23,000 --> 00:10:27,000", "arabic": "كُنْتُ أَتَأَكَّدُ مِنْ بَلَاغَةِ وَضْعِهِ وَسَلَامَةِ نَقْلِهِ يَا أُمَّ مُحَمَّدٍ", "segs": null, "full_uz": "Uning bayonining ravonligi va tarjimasining to'g'riligiga ishonch hosil qilayotgan edim, Umm Muhammad.", "note": null},
  {"num": 177, "time": "00:10:27,000 --> 00:10:29,000", "arabic": "وَكَيْفَ وَجَدْتَهَا؟", "segs": null, "full_uz": "Uni qanday topding (qanday baholading)?", "note": null},
  {"num": 178, "time": "00:10:29,000 --> 00:10:34,000", "arabic": "اَلْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي أُمَّةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى عَهْدِ هَارُونَ الرَّشِيدِ مَنْ يَحْمِلُ أَمَانَةَ الْعِلْمِ", "segs": null, "full_uz": "Payg'ambarimiz ummatida, Horun ar-Rashid davrida ilm omonatini ko'targan kishilarni yaratgan Allohga hamdlar bo'lsin.", "note": null},
  {"num": 180, "time": "00:10:34,000 --> 00:10:40,000", "arabic": "اَلْفَضْلُ لِلَّهِ أَوَّلًا ثُمَّ لِأَبِي جَعْفَرٍ هَارُونَ، فَلَوْلَا اهْتِمَامُهُ بِالْعِلْمِ وَأَهْلِهِ لَمَا بَلَغْنَا مَا نَحْنُ عَلَيْهِ مِنَ الدِّرَايَةِ وَالرِّيَادَةِ", "segs": [{"ar": "اَلْفَضْلُ لِلَّهِ أَوَّلًا ثُمَّ لِأَبِي جَعْفَرٍ هَارُونَ", "uz": "eng avval Allohga, so'ngra Abu Ja'far Horunga minnatdorchilik"}, {"ar": "فَلَوْلَا اهْتِمَامُهُ بِالْعِلْمِ وَأَهْلِهِ لَمَا بَلَغْنَا مَا نَحْنُ عَلَيْهِ مِنَ الدِّرَايَةِ وَالرِّيَادَةِ", "uz": "uning ilm va ahliga bo'lgan e'tibori bo'lmasa, biz erishgan bilim va yetakchilikka yeta olmasdik"}], "full_uz": "Eng avval Allohga, so'ngra Abu Ja'far Horunga minnatdorchilik — uning ilm va ahliga bo'lgan e'tibori bo'lmasa, biz erishgan bilim va yetakchilikka yeta olmasdik.", "note": null},
  {"num": 182, "time": "00:10:40,000 --> 00:10:45,000", "arabic": "اَلْعِلْمُ يَا زُبَيْدَةُ هُوَ الْحَيَاةُ وَالْكِتَابُ سِرُّ خُلُودِهَا، أَوَلَسْنَا أُمَّةَ اقْرَأْ", "segs": null, "full_uz": "Ilm, Zubayda, hayotning o'zi, kitob esa uning boqiyligining siridir. Biz «Iqro» (o'qi) ummati emasmizmi?", "note": "«أُمَّةُ اقْرَأْ» — «Iqro' (o'qi) ummati», ya'ni Qur'onning birinchi nozil bo'lgan «اقرأ» (o'qi) so'zi bilan boshlangan oyatga ishora qiluvchi, musulmonlarni ilmga chorlaydigan ibora."},
  {"num": 184, "time": "00:11:01,000 --> 00:11:05,000", "arabic": "أَتُدْرِكُ مَا أَنْتَ مُقْبِلٌ عَلَيْهِ يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Nima sari yuzlanayotganingni anglaysanmi, Ibn Hanbal?", "note": null},
  {"num": 185, "time": "00:11:05,000 --> 00:11:10,000", "arabic": "هَذَا أَبُو يُوسُفَ الْقَاضِي، صَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ شَيْخِ الْعِرَاقَيْنِ", "segs": null, "full_uz": "Bu — qozi Abu Yusuf, ikki Iroq shayxi Abu Hanifa an-Nu'monning shogirdi.", "note": null},
  {"num": 187, "time": "00:11:10,000 --> 00:11:14,000", "arabic": "إِنَّهُ الشَّيْخُ الَّذِي يَحْلُمُ كُلُّ طُلَّابِ الْفِقْهِ بِالتَّأَدُّبِ عَلَى يَدَيْهِ", "segs": null, "full_uz": "U — barcha fiqh talabalari uning qo'lida adab o'rganishni orzu qiladigan shayxdir.", "note": null},
  {"num": 188, "time": "00:11:14,000 --> 00:11:16,000", "arabic": "أَأَنْتَ أَهْلٌ لِتَكُونَ تِلْمِيذًا عِنْدَهُ؟", "segs": null, "full_uz": "Uning yonida shogird bo'lishga munosibmisan?", "note": null},
  {"num": 189, "time": "00:11:16,000 --> 00:11:20,000", "arabic": "يَجِبُ أَنْ تُعِدَّ الْعُدَّةَ لِمُهِمَّةٍ صَعْبَةٍ كَتِلْكَ، فَإِنَّ أَبَا يُوسُفَ لَا يَتَهَاوَنُ مَعَ أَيِّ تَقْصِيرٍ", "segs": null, "full_uz": "Bunday og'ir vazifa uchun tayyorgarlik ko'rishing kerak, chunki Abu Yusuf hech qanday kamchilikka murosa qilmaydi.", "note": null},
  {"num": 192, "time": "00:11:23,000 --> 00:11:26,000", "arabic": "أَنَسِيتَ يَا أَحْمَدُ قَوْلَ رَبِّكَ لِيَحْيَى: خُذِ الْكِتَابَ بِقُوَّةٍ", "segs": null, "full_uz": "Unutdingmi, Ahmad, Robbingning Yahyoga aytgan so'zini: «Kitobni mahkam tut»?", "note": "«خُذِ الْكِتَابَ بِقُوَّةٍ» — Qur'oni karimning Maryam surasi, 12-oyatidan, Yahyo (Yuhanno) payg'ambarga qaratilgan ilohiy amr."},
  {"num": 194, "time": "00:11:26,000 --> 00:11:30,000", "arabic": "اَللَّهُمَّ خُذْ بِيَدِ عَبْدِكَ ابْنِ حَنْبَلٍ وَأَعِنْهُ عَلَى مَا هُوَ مُقْدِمٌ عَلَيْهِ، يَا رَبِّ", "segs": null, "full_uz": "Yo Alloh, bandang Ibn Hanbalning qo'lidan tut va u boshlagan ishda unga yordam ber, yo Rabbim.", "note": null},
  {"num": 197, "time": "00:12:01,000 --> 00:12:04,000", "arabic": "كَأَنَّ الْإِمَامَ أَبَا يُوسُفَ تَأَخَّرَ عَنْ حَلْقَةِ دَرْسِهِ", "segs": null, "full_uz": "Go'yo imom Abu Yusuf dars halqasiga kechikayotganga o'xshaydi.", "note": null},
  {"num": 198, "time": "00:12:04,000 --> 00:12:06,000", "arabic": "لَا أَظُنُّهُ قَدْ تَأَخَّرَ، رُبَّمَا نَحْنُ أَتَيْنَا بُكْرَةً", "segs": null, "full_uz": "U kechikkan deb o'ylamayman, balki biz erta kelgandirmiz.", "note": null},
  {"num": 200, "time": "00:12:06,000 --> 00:12:09,000", "arabic": "أَجَدِيدَانِ أَنْتُمْ فِي حَلْقَةِ أَبِي يُوسُفَ؟", "segs": null, "full_uz": "Abu Yusuf halqasida yangimisizlar?", "note": null},
  {"num": 201, "time": "00:12:09,000 --> 00:12:10,000", "arabic": "أَجَلْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 202, "time": "00:12:10,000 --> 00:12:19,000", "arabic": "لِذَلِكَ أَرَاكُمَا مُتَحَمِّسَيْنِ، وَمَنْ ظَلَّ يَسْتَخِفُّهُ الْحَمَاسُ لِرُؤْيَةِ الْإِمَامِ أَبِي يُوسُفَ صَاحِبِ أَبِي حَنِيفَةَ النُّعْمَانِ إِمَامِ أَهْلِ الْعِرَاقِ", "segs": [{"ar": "لِذَلِكَ أَرَاكُمَا مُتَحَمِّسَيْنِ", "uz": "shuning uchun sizlarni ikkovingizni ishtiyoqli ko'ryapman"}, {"ar": "وَمَنْ ظَلَّ يَسْتَخِفُّهُ الْحَمَاسُ لِرُؤْيَةِ الْإِمَامِ أَبِي يُوسُفَ صَاحِبِ أَبِي حَنِيفَةَ النُّعْمَانِ إِمَامِ أَهْلِ الْعِرَاقِ", "uz": "va Iroq ahli imomi Abu Hanifaning shogirdi imom Abu Yusufni ko'rish ishtiyoqi hayajonlantiradiganlardan bo'lgan kishi ekan"}], "full_uz": "Shuning uchun sizlarni ikkovingizni ishtiyoqli ko'ryapman — Iroq ahli imomi Abu Hanifaning shogirdi imom Abu Yusufni ko'rish ishtiyoqi hayajonlantiradiganlardan ekansizlar.", "note": null},
  {"num": 206, "time": "00:12:19,000 --> 00:12:24,000", "arabic": "أَنَا يَحْيَى بْنُ مَعِينٍ، وَمُحَدِّثُكَ أَحْمَدُ بْنُ حَنْبَلٍ وَهَذَا صَاحِبِي مُحَمَّدُ بْنُ نُوحٍ", "segs": null, "full_uz": "Men Yahyo ibn Ma'inman, siz bilan gaplashayotgan esa Ahmad ibn Hanbal, bu esa do'stim Muhammad ibn Nuh.", "note": null},
  {"num": 208, "time": "00:12:24,000 --> 00:12:27,000", "arabic": "أَهْلًا بِكَ يَا ابْنَ حَنْبَلٍ أَهْلًا بِكَ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Xush kelibsan, Ibn Hanbal, xush kelibsan, Ibn Nuh.", "note": null},
  {"num": 209, "time": "00:12:27,000 --> 00:12:29,000", "arabic": "أَظُنُّ الشَّيْخَ أَبَا يُوسُفَ عَلَى وَشْكِ الْوُصُولِ", "segs": null, "full_uz": "Nazarimda, shayx Abu Yusuf yetib kelay demoqda.", "note": null},
  {"num": 210, "time": "00:12:29,000 --> 00:12:32,000", "arabic": "تَفَضَّلَا تَفَضَّلَا، عَلَى بَرَكَةِ اللَّهِ", "segs": null, "full_uz": "Marhamat, marhamat, Allohning barakati bilan.", "note": null},
  {"num": 212, "time": "00:12:32,000 --> 00:12:35,000", "arabic": "وَنَحْنُ أَيْضًا سَنَلْتَحِقُ بِحَلْقَةِ أَبِي يُوسُفَ الْقَاضِي", "segs": null, "full_uz": "Biz ham qozi Abu Yusuf halqasiga qo'shilamiz.", "note": null},
  {"num": 213, "time": "00:13:01,000 --> 00:13:03,000", "arabic": "أَبِي، هَذَا هُوَ الشَّابُّ الَّذِي حَدَّثْتُكَ عَنْهُ، إِنَّهُ كَنْزٌ مِنْ كُنُوزِ خُرَاسَانَ", "segs": null, "full_uz": "Otajon, mana bu senga aytgan yigitim, u Xuroson xazinalaridan bir xazina.", "note": null},
  {"num": 216, "time": "00:13:03,000 --> 00:13:09,000", "arabic": "يَجِبُ أَنْ يَكُونَ كَذَلِكَ وَإِلَّا فَقَدْ أَضَعْتَ وَقْتَنَا عَبَثًا يَا جَعْفَرُ", "segs": null, "full_uz": "Shunday bo'lishi kerak, aks holda vaqtimizni behuda sarflagan bo'lasan, Ja'far.", "note": null},
  {"num": 219, "time": "00:13:09,000 --> 00:13:12,000", "arabic": "أَرْجُو أَنْ لَا يُخَيِّبَ ظَنَّ الْأَمِيرِ يَحْيَى الْبَرْمَكِيِّ بِهِ", "segs": null, "full_uz": "Umid qilamanki, amir Yahyo al-Barmakiyning unga bo'lgan umidini oqlaydi.", "note": null},
  {"num": 220, "time": "00:13:12,000 --> 00:13:17,000", "arabic": "مَا اسْمُكَ يَا مَنْ أَذْهَلْتَ جَعْفَرًا حَتَّى جَعَلْتَهُ لَا يَنِي فِي ذِكْرِكَ؟", "segs": null, "full_uz": "Ismingiz nima, ey Ja'farni hayratda qoldirib, uni sizni doim tilga olishga majbur qilgan kishi?", "note": "«لَا يَنِي» — «to'xtamaydi, tinmaydi» ma'nosidagi klassik ibora."},
  {"num": 221, "time": "00:13:17,000 --> 00:13:19,000", "arabic": "خَادِمُكَ الْفَضْلُ بْنُ سَهْلٍ السَّرَخْسِيُّ", "segs": null, "full_uz": "Xizmatkoringiz Fadl ibn Sahl as-Sarahsiyman.", "note": null},
  {"num": 222, "time": "00:13:19,000 --> 00:13:21,000", "arabic": "وَمَا الَّذِي تُجِيدُهُ غَيْرَ أَنَّكَ مِنْ سَرَخْسَ؟", "segs": null, "full_uz": "Saraxsdan ekaningdan boshqa yana nimalarni bilasan?", "note": null},
  {"num": 223, "time": "00:13:21,000 --> 00:13:26,000", "arabic": "إِنَّ خَادِمَكَ يُجِيدُ الْفَارِسِيَّةَ كَمَا يُجِيدُ الْعَرَبِيَّةَ، كَمَا أَنَّ لِي بَاعًا فِي عِلْمِ النُّجُومِ", "segs": null, "full_uz": "Xizmatkoringiz forscha va arabchani bab-baravar biladi, shuningdek, yulduzlar ilmida ham tajribam bor.", "note": null},
  {"num": 225, "time": "00:13:26,000 --> 00:13:31,000", "arabic": "جَمِيلٌ يَا فَضْلُ، لَكِنْ دَعْنَا مِنَ النُّجُومِ الْآنَ، أُرِيدُ أَنْ أَخْتَبِرَكَ فِي التَّرْجَمَةِ", "segs": null, "full_uz": "Yaxshi, Fadl, lekin hozir yulduzlarni qo'yib tur, seni tarjimada sinab ko'rmoqchiman.", "note": null},
  {"num": 228, "time": "00:13:31,000 --> 00:13:35,000", "arabic": "عِنْدِي كِتَابٌ فَارِسِيٌّ قَيِّمٌ أُرِيدُ نَقْلَهُ إِلَى الْعَرَبِيَّةِ", "segs": null, "full_uz": "Menda qimmatli forscha kitob bor, uni arabchaga o'girishni istayman.", "note": null},
  {"num": 230, "time": "00:13:35,000 --> 00:13:40,000", "arabic": "فَإِنْ أَجَدْتَ كَافَأْتُكَ وَإِلَّا فَلَا حَاجَةَ لَنَا بِكَ", "segs": null, "full_uz": "Agar uddasidan chiqsang, mukofotlayman, aks holda senga ehtiyojimiz yo'q.", "note": null},
  {"num": 233, "time": "00:13:40,000 --> 00:13:45,000", "arabic": "أَعْلَمُ أَنَّ الْكَثِيرِينَ يَقِفُونَ عِنْدَ بَابِنَا، لَكِنَّنَا لَا نُقَرِّبُ إِلَّا النُّجَبَاءَ الْأَوْفِيَاءَ", "segs": null, "full_uz": "Bilamanki, ko'plar eshigimiz oldida turishadi, lekin biz faqat aqlli va sodiq kishilarnigina yaqinlashtiramiz.", "note": null},
  {"num": 235, "time": "00:13:45,000 --> 00:13:50,000", "arabic": "اَلْأَوْفِيَاءُ؟ أَمَّا الْوَفَاءُ يَا مَوْلَايَ فَهُوَ يُنْبِئُ عَنْ نَفْسِهِ لَا صَاحِبِهِ، وَسَتُنْبِئُكَ الْأَيَّامُ عَنِّي مَا تُحِبُّ", "segs": [{"ar": "اَلْأَوْفِيَاءُ؟ أَمَّا الْوَفَاءُ يَا مَوْلَايَ فَهُوَ يُنْبِئُ عَنْ نَفْسِهِ لَا صَاحِبِهِ", "uz": "sodiqlarmi? Sodiqlik, xo'jayinim, o'zi haqida gapiradi, egasi haqida emas"}, {"ar": "وَسَتُنْبِئُكَ الْأَيَّامُ عَنِّي مَا تُحِبُّ", "uz": "kunlar esa sizga men haqimda yoqtirgan narsangizni ko'rsatadi"}], "full_uz": "Sodiqlarmi? Sodiqlik, xo'jayinim, o'zi haqida gapiradi, egasi haqida emas — kunlar esa sizga men haqimda yoqtirgan narsangizni ko'rsatadi.", "note": null},
  {"num": 239, "time": "00:13:50,000 --> 00:13:55,000", "arabic": "أَمَّا النَّجَابَةُ فَاقْذِفْ بِي حَيْثُ شِئْتَ وَانْظُرْنِي حَيْثُ تَشْتَهِي", "segs": null, "full_uz": "Aqlga kelsak, meni xohlagan yeringizga tashlang va xohlagan tarzda sinab ko'ring.", "note": null},
  {"num": 242, "time": "00:13:55,000 --> 00:13:59,000", "arabic": "أَخْبَرَنِي جَعْفَرٌ أَنَّكَ لَسْتَ عَلَى مِلَّةِ مُحَمَّدٍ، مُخْطِئٌ أَنَا؟", "segs": null, "full_uz": "Ja'far senga Muhammad dinida emassan dedi, xato qilyapmanmi?", "note": null},
  {"num": 244, "time": "00:13:59,000 --> 00:14:04,000", "arabic": "إِنَّمَا الْأَمْرُ كَذَلِكَ يَا مَوْلَايَ، أَنَا مَجُوسِيٌّ", "segs": null, "full_uz": "Ish shunday, xo'jayinim, men majusiyman.", "note": null},
  {"num": 246, "time": "00:14:31,000 --> 00:14:40,000", "arabic": "قَالَ الْإِمَامُ أَبُو حَنِيفَةَ رَحِمَهُ اللَّهُ: آخُذُ بِكِتَابِ اللَّهِ، فَإِنْ لَمْ أَجِدْ فَبِسُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": [{"ar": "قَالَ الْإِمَامُ أَبُو حَنِيفَةَ رَحِمَهُ اللَّهُ: آخُذُ بِكِتَابِ اللَّهِ", "uz": "imom Abu Hanifa — Alloh unga rahm qilsin — dedi: «Men Alloh kitobini olaman»"}, {"ar": "فَإِنْ لَمْ أَجِدْ فَبِسُنَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "uz": "topmasam, Rasululloh sunnati bilan (amal qilaman)"}], "full_uz": "Imom Abu Hanifa — Alloh unga rahm qilsin — dedi: «Men Alloh kitobini olaman, topmasam, Rasululloh sunnati bilan».", "note": "Bu — imom Abu Hanifaning fiqhiy manbalar tartibi haqidagi mashhur so'zlaridan bir qismi."},
  {"num": 251, "time": "00:14:40,000 --> 00:14:47,000", "arabic": "فَإِنْ لَمْ أَجِدْ أَخَذْتُ بِقَوْلِ أَصْحَابِهِ، أَمَّا مَا جَاءَ عَنْ غَيْرِهِمْ فَهُمْ رِجَالٌ وَنَحْنُ رِجَالٌ", "segs": [{"ar": "فَإِنْ لَمْ أَجِدْ أَخَذْتُ بِقَوْلِ أَصْحَابِهِ", "uz": "topmasam, sahobalari so'ziga amal qilaman"}, {"ar": "أَمَّا مَا جَاءَ عَنْ غَيْرِهِمْ فَهُمْ رِجَالٌ وَنَحْنُ رِجَالٌ", "uz": "boshqalardan kelgan gaplarga kelsak, ular ham odam, biz ham odammiz"}], "full_uz": "Topmasam, sahobalari so'ziga amal qilaman. Boshqalardan kelgan gaplarga kelsak, ular ham odam, biz ham odammiz.", "note": "Bu — imom Abu Hanifaga nisbat berilgan mashhur gap, ijtihod erkinligini bildiradi: undan keyingi fuqaholarning fikri muqaddas emas, tanqid qilinishi mumkin."},
  {"num": 255, "time": "00:14:47,000 --> 00:14:52,000", "arabic": "كَذَبَ وَاللَّهِ وَافْتَرَى عَلَيْنَا مَنْ يَقُولُ عَنَّا إِنَّنَا نُقَدِّمُ الْقِيَاسَ عَلَى النَّصِّ", "segs": null, "full_uz": "Vallohi, biz naqldan (nass) ko'ra qiyosni ustun qo'yamiz, deb aytgan kishi yolg'on so'zlab, bizga tuhmat qilibdi.", "note": null},
  {"num": 257, "time": "00:14:52,000 --> 00:14:56,000", "arabic": "وَهَلْ يُحْتَاجُ بَعْدَ النَّصِّ إِلَى قِيَاسٍ؟", "segs": null, "full_uz": "Naqldan (nass) keyin qiyosga ehtiyoj bo'ladimi?", "note": null},
  {"num": 258, "time": "00:15:07,000 --> 00:15:10,000", "arabic": "أَنَا بَائِعُ طِيبٍ، تَفَضَّلْ يَا أَخِي", "segs": null, "full_uz": "Men atir sotuvchiman, marhamat, birodarim.", "note": null},
  {"num": 261, "time": "00:15:10,000 --> 00:15:14,000", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 262, "time": "00:15:14,000 --> 00:15:17,000", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 263, "time": "00:15:17,000 --> 00:15:20,000", "arabic": "تَفَضَّلْ تَفَضَّلْ تَفَضَّلْ إِلَى الدَّاخِلِ", "segs": null, "full_uz": "Marhamat, marhamat, ichkariga kiring.", "note": null},
  {"num": 264, "time": "00:15:34,000 --> 00:15:38,000", "arabic": "أَتَعْرِفُ بِأَيِّ يَدٍ يَصِلُ هَذَا الْكِتَابُ؟ كُلُّ مَا يَجْرِي فِي السُّوقِ مَكْتُوبٌ فِي هَذِهِ الرُّقْعَةِ", "segs": null, "full_uz": "Bu maktub qanday yetkazilishini bilasanmi? Bozorda bo'layotgan har bir narsa shu varaqda yozilgan.", "note": null},
  {"num": 266, "time": "00:15:38,000 --> 00:15:41,000", "arabic": "اُنْقُلْ سَلَامِي لِجَنَابِ الْوَالِي", "segs": null, "full_uz": "Salomimni voliy janoblariga yetkazing.", "note": null},
  {"num": 268, "time": "00:16:01,000 --> 00:16:05,000", "arabic": "لَقَدْ أَصْبَحَ جَدِيدًا، تَسْتَطِيعُ الْآنَ أَنْ تُسَابِقَ بِهِ خُيُولَ الْبَرِيدِ", "segs": null, "full_uz": "Endi u yangidek bo'ldi, endi u bilan pochta otlari bilan poyga qilsa bo'ladi.", "note": null},
  {"num": 270, "time": "00:16:05,000 --> 00:16:08,000", "arabic": "شُكْرًا لَكَ، مَعَ السَّلَامَةِ", "segs": null, "full_uz": "Rahmat sizga, xayr.", "note": null},
  {"num": 272, "time": "00:16:31,000 --> 00:16:35,000", "arabic": "أَبَا دُلَامَةَ", "segs": null, "full_uz": "Abu Dulama.", "note": null},
  {"num": 274, "time": "00:16:35,000 --> 00:16:40,000", "arabic": "لِمَاذَا لَمْ تَأْتِ لِأَخْذِ نَعْلِكَ يَا أَبَا دُلَامَةَ؟", "segs": null, "full_uz": "Nega na'lingni olishga kelmading, Abu Dulama?", "note": null},
  {"num": 276, "time": "00:16:40,000 --> 00:16:43,000", "arabic": "لَقَدْ أَصْبَحَتْ جَدِيدَةً، وَمَنْ طَلَبَ مِنْكَ ذَلِكَ؟", "segs": null, "full_uz": "U yangidek bo'ldi-ku. Kim sendan buni so'radi?", "note": null},
  {"num": 278, "time": "00:16:43,000 --> 00:16:47,000", "arabic": "أَلَمْ أَقُلْ لَكَ أَعْطِهَا لِحَافِي؟ اِحْرِقْهَا، اِرْمِهَا فِي الْقُمَامَةِ", "segs": null, "full_uz": "Senga uni yalangoyoqlarga ber demadimmi? Kuydir, axlatga tashla.", "note": null},
  {"num": 281, "time": "00:16:47,000 --> 00:16:52,000", "arabic": "نَعْلٌ مُهْتَرِئَةٌ، وَتُرِيدُ أَيْضًا ثَمَنَ إِصْلَاحِهَا؟", "segs": null, "full_uz": "Eskirgan na'l-u, ustiga uning ta'mirlash haqini ham so'raysanmi?", "note": null},
  {"num": 284, "time": "00:16:52,000 --> 00:16:56,000", "arabic": "سَامَحَكَ اللَّهُ يَا أَبَا دُلَامَةَ، كَيْفَ تَقُولُ عَنِ النَّعْلِ إِنَّهَا مُهْتَرِئَةٌ؟", "segs": null, "full_uz": "Alloh seni kechirsin, Abu Dulama, na'lni qanday qilib eskirgan deysan?", "note": null},
  {"num": 286, "time": "00:16:56,000 --> 00:17:01,000", "arabic": "اُنْظُرْ إِلَيْهَا، تَأَمَّلْهَا، مَا بِكَ يَا أَبَا دُلَامَةَ، تَكَادُ لَا تَعْرِفُ نَعْلَكَ", "segs": null, "full_uz": "Unga qara, diqqat bilan boq. Senga nima bo'ldi, Abu Dulama, o'z na'lingni tanimay qolayapsan.", "note": null},
  {"num": 290, "time": "00:17:01,000 --> 00:17:05,000", "arabic": "لَوْ وَقَعَتْ عَلَيْهَا عَيْنُ لِصٍّ لَرَاوَدَكَ عَلَى قَدَمِكَ", "segs": null, "full_uz": "Agar o'g'rining ko'zi tushsa, oyog'ingdan uni yechib olishga jur'at etardi.", "note": null},
  {"num": 292, "time": "00:17:05,000 --> 00:17:08,000", "arabic": "هَاتِ وَكَمْ تُرِيدُ؟ وَلَكِنْ إِيَّاكَ وَالطَّمَعَ أَيُّهَا الْإِسْكَافِيُّ", "segs": null, "full_uz": "Qani, qancha xohlaysan? Lekin ochko'zlikdan saqlan, ey etikdo'z.", "note": null},
  {"num": 294, "time": "00:17:08,000 --> 00:17:11,000", "arabic": "طَمَعٌ أَيُّ طَمَعٍ يَا أَبَا دُلَامَةَ، دَرَاهِمُكَ عَلَيَّ شَحِيحَةٌ", "segs": null, "full_uz": "Ochko'zlikmi, qaysi ochko'zlik, Abu Dulama, dirhamlaring menga qizg'anch emas.", "note": null},
  {"num": 296, "time": "00:17:11,000 --> 00:17:15,000", "arabic": "لَا لَا لَا لَا أُرِيدُ شَيْئًا مِنْ جَيْبِكَ", "segs": null, "full_uz": "Yo'q, yo'q, yo'q, cho'ntagingdan hech narsa xohlamayman.", "note": null},
  {"num": 297, "time": "00:17:15,000 --> 00:17:19,000", "arabic": "أَمْسِكْ هَذَا نِصْفَ دِرْهَمٍ", "segs": null, "full_uz": "Mana, yarim dirhamni ol.", "note": null},
  {"num": 298, "time": "00:17:19,000 --> 00:17:23,000", "arabic": "نِصْفُ دِرْهَمٍ؟ قُلْتُ لَكَ لَا أُرِيدُ شَيْئًا يَا أَبَا دُلَامَةَ", "segs": null, "full_uz": "Yarim dirhammi? Senga hech narsa xohlamayman dedim-ku, Abu Dulama.", "note": null},
  {"num": 299, "time": "00:17:23,000 --> 00:17:27,000", "arabic": "هَذَا النَّعْلُ هَدِيَّةٌ مِنِّي إِلَيْكَ", "segs": null, "full_uz": "Bu na'l mendan senga sovg'a.", "note": null},
  {"num": 300, "time": "00:17:27,000 --> 00:17:30,000", "arabic": "مُنْذُ مَتَى تَعْمَلُ بِدُونِ مُقَابِلٍ؟", "segs": null, "full_uz": "Qachondan beri hech narsasiz ishlaysan?", "note": null},
  {"num": 301, "time": "00:17:30,000 --> 00:17:33,000", "arabic": "كَأَنَّكَ تُرِيدُ مِنِّي شَيْئًا، قُلْ هَيَّا", "segs": null, "full_uz": "Menda biror ishing bordekku, ayt, tez.", "note": null},
  {"num": 303, "time": "00:17:33,000 --> 00:17:37,000", "arabic": "أُرِيدُ أُرِيدُ يَا أَبَا دُلَامَةَ الزَّوَاجَ، أُرِيدُ أَنْ أَتَزَوَّجَ", "segs": null, "full_uz": "Xohlayman, uylanishni xohlayman, Abu Dulama, uylanmoqchiman.", "note": null},
  {"num": 305, "time": "00:18:01,000 --> 00:18:04,000", "arabic": "يَا عَامِرُ، أَيْنَ أَنْتَ يَا جِهْبِذَ الْعَصْرِ وَالْأَوَانِ؟", "segs": null, "full_uz": "Omir, zamona ustozi, qayerdasan?", "note": null},
  {"num": 308, "time": "00:18:04,000 --> 00:18:06,000", "arabic": "عَامِرُ", "segs": null, "full_uz": "Omir!", "note": null},
  {"num": 309, "time": "00:18:06,000 --> 00:18:10,000", "arabic": "قَبَّحَكَ اللَّهُ يَا إِسْكَافِيَ الشُّؤْمِ، أَيُّهَا الْأَحْمَقُ الْقَبِيحُ", "segs": null, "full_uz": "Alloh seni la'natlasin, ey shumtaka etikdo'z, ey xunuk ahmoq.", "note": null},
  {"num": 311, "time": "00:18:10,000 --> 00:18:13,000", "arabic": "هَكَذَا تَقْضِي وَقْتَكَ، تَقْضِيهِ بِالثَّرْثَرَةِ", "segs": null, "full_uz": "Vaqtingni shunday o'tkazasanmi, valaqlash bilan?", "note": null},
  {"num": 313, "time": "00:18:13,000 --> 00:18:16,000", "arabic": "أُمِّي أُمِّي", "segs": null, "full_uz": "Onajon, onajon!", "note": null},
  {"num": 314, "time": "00:18:16,000 --> 00:18:19,000", "arabic": "مَاذَا تَفْعَلُ هُنَا؟ مَاذَا تَفْعَلُ هُنَا أَيُّهَا الْأَحْمَقُ؟", "segs": null, "full_uz": "Bu yerda nima qilyapsan? Bu yerda nima qilyapsan, ey ahmoq?", "note": null},
  {"num": 315, "time": "00:18:19,000 --> 00:18:21,000", "arabic": "أُمِّي اهْدَئِي يَا أُمِّي", "segs": null, "full_uz": "Onajon, xotirjam bo'l, onajon.", "note": null},
  {"num": 316, "time": "00:18:21,000 --> 00:18:26,000", "arabic": "عُدْ إِلَى دُكَّانِكَ قَبْلَ أَنْ أَجْعَلَ مِنْكَ أُضْحُوكَةَ السُّوقِ، هَيَّا عُدْ", "segs": null, "full_uz": "Seni bozorning kulgi mavzusiga aylantirmasimdan, do'koningga qayt, tez, qayt.", "note": null},
  {"num": 320, "time": "00:18:26,000 --> 00:18:28,000", "arabic": "حَاضِرٌ يَا أُمِّي", "segs": null, "full_uz": "Xo'p bo'ladi, onajon.", "note": null},
  {"num": 321, "time": "00:18:28,000 --> 00:18:33,000", "arabic": "أُمِّي، جِدِّي لَهُ زَوْجَةً يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Onajon, uni jiddiy o'yla, unga xotin top, Umm Omir.", "note": null},
  {"num": 325, "time": "00:18:33,000 --> 00:18:38,000", "arabic": "وَالْحَقُّ مُنْذُ أَخْبَرْتُكَ أَنِّي سَأُزَوِّجُكَ صِرْتَ مِلْحَاحًا فِي طَلَبِ الزَّوَاجِ", "segs": null, "full_uz": "Rostini aytsam, senga uylantiraman deganimdan beri uylanish haqida qat'iy talab qilaverasan.", "note": null},
  {"num": 327, "time": "00:18:38,000 --> 00:18:42,000", "arabic": "أُمِّي، وَتُخْبِرِي كُلَّ مَنْ هَبَّ وَدَرَّ", "segs": null, "full_uz": "Onajon, va har bir tasodifiy odamga aytib yurasan.", "note": "«كُلُّ مَنْ هَبَّ وَدَرَّ» — «kelgan-ketgan har kim», ya'ni tasodifiy, oddiy odamlar ma'nosidagi ibora."},
  {"num": 329, "time": "00:18:42,000 --> 00:18:47,000", "arabic": "أُمِّي أَنَا أَهْوَى زَوَاجِي، أَنَا أَهْوَى زَوَاجِي", "segs": null, "full_uz": "Onajon, men o'z uylanishimni xohlayman, men o'z uylanishimni xohlayman.", "note": null},
  {"num": 331, "time": "00:18:47,000 --> 00:18:51,000", "arabic": "أَعَانَكَ اللَّهُ", "segs": null, "full_uz": "Alloh senga yordam bersin.", "note": null},
  {"num": 332, "time": "00:19:01,000 --> 00:19:06,000", "arabic": "فَوْزُ سَأَفُكُّ قَيْدَكِ لِتَغْتَسِلِي وَتَتَزَيَّنِي، هُنَاكَ رَجُلٌ يُرِيدُ شِرَاءَكِ", "segs": null, "full_uz": "Favz, kishaningni yechaman, cho'milib, bezanish uchun — seni sotib olmoqchi bo'lgan bir odam bor.", "note": null},
  {"num": 334, "time": "00:19:06,000 --> 00:19:11,000", "arabic": "أُرِيدُكِ أَنْ تَكُونِي بِأَبْهَى حُلَّةٍ، فَكُلَّمَا ازْدَادَ جَمَالُكِ ازْدَادَ سِعْرُكِ", "segs": null, "full_uz": "Seni eng chiroyli holatda ko'rishni istayman — go'zalliging qanchalik ortsa, narxing ham shunchalik oshadi.", "note": null},
  {"num": 336, "time": "00:19:11,000 --> 00:19:16,000", "arabic": "أَنَا حُرَّةٌ، لَسْتُ أَنَا مَنْ تُبَاعُ أَوْ تُشْتَرَى، وَسَأَبْقَى حُرَّةً دَائِمًا", "segs": null, "full_uz": "Men erkinman, men sotiladigan yoki sotib olinadigan kishi emasman, va hamisha erkin bo'lib qolaman.", "note": null},
  {"num": 339, "time": "00:19:16,000 --> 00:19:24,000", "arabic": "لَيْسَ هَذَا فَحَسْبُ، أَنَا مَنْ سَيَكْشِفُ أَمْرَكِ عَلَى أَعْيُنِ النَّاسِ لِتَنَالِي جَزَاءَ مَا تَقْتَرِفِينَ", "segs": null, "full_uz": "Bu bilan tugamaydi, men bo'laman sirni odamlar ko'z o'ngida fosh qiladigan, toki qilmishing jazosini olguningcha.", "note": null},
  {"num": 342, "time": "00:19:24,000 --> 00:19:31,000", "arabic": "اِسْمَعِي أَيَّتُهَا الْفَتَاةُ الْحَمْقَاءُ، لَنْ تَخْرُجِي مِنْ هَذِهِ الدَّارِ إِلَّا إِلَى الْقَبْرِ أَوْ إِلَى بَيْتِ الرَّجُلِ الَّذِي سَيَشْتَرِيكِ", "segs": [{"ar": "اِسْمَعِي أَيَّتُهَا الْفَتَاةُ الْحَمْقَاءُ", "uz": "eshit, ey ahmoq qiz"}, {"ar": "لَنْ تَخْرُجِي مِنْ هَذِهِ الدَّارِ إِلَّا إِلَى الْقَبْرِ أَوْ إِلَى بَيْتِ الرَّجُلِ الَّذِي سَيَشْتَرِيكِ", "uz": "bu uydan faqat qabrga yoki seni sotib oladigan odamning uyiga chiqasan"}], "full_uz": "Eshit, ey ahmoq qiz, bu uydan faqat qabrga yoki seni sotib oladigan odamning uyiga chiqasan.", "note": null},
  {"num": 345, "time": "00:19:31,000 --> 00:19:39,000", "arabic": "لَيْسَ هَذَا فَحَسْبُ، سَتَسْمَعِينَ كَلَامِي رَغْمًا عَنْكِ، وَإِنْ لَمْ يَنْفَعْ مَعَكِ الْكَلَامُ اللَّيِّنُ فَإِنَّ السِّيَاطَ سَتَفْعَلُ فِعْلَهَا مَعَكِ", "segs": [{"ar": "لَيْسَ هَذَا فَحَسْبُ، سَتَسْمَعِينَ كَلَامِي رَغْمًا عَنْكِ", "uz": "bu bilan tugamaydi, xohlasang-xohlamasang gapimni tinglaysan"}, {"ar": "وَإِنْ لَمْ يَنْفَعْ مَعَكِ الْكَلَامُ اللَّيِّنُ فَإِنَّ السِّيَاطَ سَتَفْعَلُ فِعْلَهَا مَعَكِ", "uz": "va agar yumshoq gap foyda bermasa, qamchi o'z ishini qiladi"}], "full_uz": "Bu bilan tugamaydi, xohlasang-xohlamasang gapimni tinglaysan, va agar yumshoq gap foyda bermasa, qamchi o'z ishini qiladi.", "note": null},
  {"num": 349, "time": "00:19:39,000 --> 00:19:47,000", "arabic": "لَوْ حَزَزْتِ رَقَبَتِي بِالسَّيْفِ لَنْ تَسْمَعِي مِنِّي إِلَّا مَا سَمِعْتِهِ، وَلَنْ أَسْمَحَ لَكِ بِبَيْعِي أَبَدًا", "segs": null, "full_uz": "Bo'ynimni qilich bilan kessang ham, mendan faqat eshitganingnigina eshitasan, va meni sotishingga hech qachon yo'l qo'ymayman.", "note": null},
  {"num": 352, "time": "00:19:47,000 --> 00:19:51,000", "arabic": "فَسَتَرَيْنَ، سَنَرَى", "segs": null, "full_uz": "Ko'rasan. — Ko'ramiz.", "note": null},
  {"num": 354, "time": "00:20:01,000 --> 00:20:06,000", "arabic": "مَا بِكَ يَا هَارُونُ؟ مُنْذُ مُدَّةٍ وَأَنْتَ عَلَى هَذِهِ الْحَالِ", "segs": null, "full_uz": "Senga nima bo'ldi, Horun? Bir muddatdan beri shu holdasan.", "note": null},
  {"num": 356, "time": "00:20:06,000 --> 00:20:10,000", "arabic": "أَصْلَحَ اللَّهُ بَالَ الْأَمِيرِ، مَا الَّذِي يَشْغَلُ خَاطِرَكَ لِتَبْقَى وَحِيدًا هَكَذَا؟", "segs": null, "full_uz": "Alloh amirning ko'nglini xotirjam qilsin, seni shunday yolg'iz qoldirgan narsa nima?", "note": null},
  {"num": 358, "time": "00:20:10,000 --> 00:20:14,000", "arabic": "لَا شَيْءَ يَا زُبَيْدَةُ لَا شَيْءَ، غَايَةُ الْأَمْرِ أَنَّنِي مَشْغُولُ الْبَالِ عَلَى إِمَامِنَا مَالِكِ بْنِ أَنَسٍ", "segs": null, "full_uz": "Hech narsa, Zubayda, hech narsa. Faqat imomimiz Molik ibn Anas haqida xayolim band.", "note": null},
  {"num": 360, "time": "00:20:14,000 --> 00:20:20,000", "arabic": "هَوِّنْ عَلَيْكَ يَا هَارُونُ، هَوِّنْ عَلَيْكَ", "segs": null, "full_uz": "O'zingga yengil tut, Horun, o'zingga yengil tut.", "note": null},
  {"num": 362, "time": "00:20:20,000 --> 00:20:26,000", "arabic": "عَسَى اللَّهُ أَنْ يَمُنَّ عَلَيْهِ بِالْعَافِيَةِ وَيُطِيلَ بِعُمْرِهِ لِيُفِيدَنَا بِعِلْمِهِ وَمَعْرِفَتِهِ", "segs": null, "full_uz": "Alloh unga shifo va uzoq umr ato qilsin, toki ilmi va bilimi bilan bizga foyda keltirsin.", "note": null},
  {"num": 365, "time": "00:20:26,000 --> 00:20:32,000", "arabic": "كُنْتُ أَرْجُو أَنْ أَكُونَ بِجِوَارِهِ لَحْظَةَ ابْتِلَائِهِ بِالْمَرَضِ، لَعَلَّ اللَّهَ يُعِينُنِي عَلَى تَدْبِيرِ أَمْرِهِ وَإِصْلَاحِ شَأْنِهِ لِيَتَجَاوَزَ مَرَضَهُ", "segs": [{"ar": "كُنْتُ أَرْجُو أَنْ أَكُونَ بِجِوَارِهِ لَحْظَةَ ابْتِلَائِهِ بِالْمَرَضِ", "uz": "kasal bo'lganida yonida bo'lishni orzu qilardim"}, {"ar": "لَعَلَّ اللَّهَ يُعِينُنِي عَلَى تَدْبِيرِ أَمْرِهِ وَإِصْلَاحِ شَأْنِهِ لِيَتَجَاوَزَ مَرَضَهُ", "uz": "shoyad Alloh uning ishini yaxshilashda menga yordam bersa, kasalligini yengib chiqishi uchun"}], "full_uz": "Kasal bo'lganida yonida bo'lishni orzu qilardim, shoyad Alloh uning ishini yaxshilashda menga yordam bersa, kasalligini yengib chiqishi uchun.", "note": null},
  {"num": 367, "time": "00:20:32,000 --> 00:20:37,000", "arabic": "هَوِّنْ عَلَيْكَ يَا هَارُونُ، فَمَا مَنَعَكَ عَنْ مُلَازَمَتِهِ إِلَّا أَعْبَاءُ الْخِلَافَةِ وَشُؤُونُ الْحُكْمِ", "segs": null, "full_uz": "O'zingga yengil tut, Horun, seni unga hamroh bo'lishdan faqat xalifalik yuklari va hukmronlik ishlari to'sib qo'ygan.", "note": null},
  {"num": 368, "time": "00:20:37,000 --> 00:20:41,000", "arabic": "اُدْعُ لَهُ بِالشِّفَاءِ وَجِدْ مَنْ يَهْتَمُّ بِأَمْرِهِ وَيَقُومُ عَلَى إِصْلَاحِ شَأْنِهِ", "segs": null, "full_uz": "Unga shifo tila va uning ishlariga g'amxo'rlik qiladigan kishini top.", "note": null},
  {"num": 369, "time": "00:20:41,000 --> 00:20:46,000", "arabic": "أَسْأَلُ اللَّهَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَ إِمَامَ دَارِ الْهِجْرَةِ وَيَحْفَظَهُ ذُخْرًا لِلْإِسْلَامِ وَنَفْعًا لِلْمُسْلِمِينَ", "segs": null, "full_uz": "Buyuk arsh Robbisi Allohdan hijrat diyori imomiga shifo berishini va uni Islom uchun zaxira, musulmonlar uchun foyda qilib saqlashini so'rayman.", "note": null},
  {"num": 381, "time": "00:21:31,000 --> 00:21:35,000", "arabic": "حَنْظَلَةُ، مَاذَا تَفْعَلُ هُنَا؟ لِمَاذَا تَجْلِسُ عِنْدَ نَافِذَةِ هَذِهِ الْمَأْفُونَةِ؟", "segs": null, "full_uz": "Hanzala, bu yerda nima qilyapsan? Nega bu ahmoq (qiz)ning derazasi yonida o'tiribsan?", "note": null},
  {"num": 384, "time": "00:21:35,000 --> 00:21:38,000", "arabic": "لَا شَيْءَ لَا شَيْءَ كُنْتُ مُتْعَبًا فَجَلَسْتُ أَسْتَرِيحُ", "segs": null, "full_uz": "Hech narsa, hech narsa, charchagandim, shuning uchun dam olgani o'tirdim.", "note": null},
  {"num": 385, "time": "00:21:38,000 --> 00:21:41,000", "arabic": "وَلَمْ تَجِدْ مَكَانًا لِتَسْتَرِيحَ فِيهِ إِلَّا هُنَا؟", "segs": null, "full_uz": "Dam olishga shu yerdan boshqa joy topolmadingmi?", "note": null},
  {"num": 386, "time": "00:21:41,000 --> 00:21:44,000", "arabic": "وَمَا بِهِ هَذَا الْمَكَانُ؟ مِثْلُهُ مِثْلُ أَيِّ مَكَانٍ آخَرَ", "segs": null, "full_uz": "Bu joyda nima ayb bor? Boshqa har qanaqa joy kabi bir joy-da.", "note": null},
  {"num": 387, "time": "00:21:44,000 --> 00:21:48,000", "arabic": "قُمْ قُمْ، وَجَهِّزْ لَنَا شَيْئًا لِنَأْكُلَهُ", "segs": null, "full_uz": "Tur, tur, va bizga yeydigan narsa tayyorla.", "note": null},
  {"num": 389, "time": "00:22:01,000 --> 00:22:06,000", "arabic": "سَأَجْعَلُكِ تَنْدَمِينَ عَلَى نَظَرَاتِكِ الْوَقِحَةِ، أَعِدُكِ بِذَلِكَ", "segs": null, "full_uz": "Seni beadab nazarlaring uchun pushaymon qildiraman, senga va'da beraman.", "note": null},
  {"num": 391, "time": "00:22:31,000 --> 00:22:36,000", "arabic": "قَاضِي الْقُضَاةِ إِنَّهُ أَبُو يُوسُفَ يَعْقُوبُ بْنُ حَبِيبٍ، صَاحِبُ أَبِي حَنِيفَةَ النُّعْمَانِ", "segs": null, "full_uz": "Qozilar qozisi — bu Abu Yusuf Ya'qub ibn Habib, Abu Hanifa an-Nu'monning shogirdi.", "note": null},
  {"num": 393, "time": "00:22:36,000 --> 00:22:40,000", "arabic": "إِنَّهُ يَنْضَحُ عِلْمًا وَيَرْتَفِعُ تَوَاضُعًا يَا أُمَّاهُ", "segs": null, "full_uz": "U ilmga to'lib toshgan-u, kamtarlikda esa ulug'vor, onajon.", "note": null},
  {"num": 394, "time": "00:22:40,000 --> 00:22:45,000", "arabic": "اَلتَّوَاضُعُ زِينَةُ الْعُلَمَاءِ وَمِرْآةُ الْفُقَهَاءِ يَا وَلَدِي", "segs": null, "full_uz": "Kamtarlik — olimlarning ziynati va fuqahoning ko'zgusidir, o'g'lim.", "note": null},
  {"num": 395, "time": "00:22:45,000 --> 00:22:50,000", "arabic": "وَأَوَّلُ ذَنْبٍ عُصِيَ بِهِ اللَّهُ سُبْحَانَهُ وَتَعَالَى فِي السَّمَاءِ قَبْلَ الْأَرْضِ هُوَ الْغُرُورُ", "segs": null, "full_uz": "Osmon va yerdan avval, Allohga qarshi qilingan birinchi gunoh — kibr edi.", "note": "Iblisning takabburligi va Odam alayhissalomga sajda qilishdan bosh tortishi voqeasiga ishora."},
  {"num": 396, "time": "00:22:50,000 --> 00:22:55,000", "arabic": "وَكَانَ جَزَاؤُهُ اللَّعْنَ مِنَ الرَّحْمَةِ وَالْخُرُوجَ مِنَ النَّعِيمِ", "segs": null, "full_uz": "Va uning jazosi rahmatdan la'natlanish va ne'matdan chiqarilish bo'ldi.", "note": null},
  {"num": 397, "time": "00:22:55,000 --> 00:23:00,000", "arabic": "عَلَّمَكَ اللَّهُ عِلْمَ الْأَنْبِيَاءِ يَا وَلَدِي وَزَيَّنَكَ بِالتَّوَاضُعِ", "segs": null, "full_uz": "Alloh senga payg'ambarlar ilmini o'rgatsin, o'g'lim, va seni kamtarlik bilan ziynatlasin.", "note": null},
  {"num": 398, "time": "00:23:00,000 --> 00:23:06,000", "arabic": "اِسْمَعْ يَا بُنَيَّ يَجِبُ أَنْ تَضَعَ نُصْبَ عَيْنَيْكَ أَمْرَيْنِ اثْنَيْنِ لَا ثَالِثَ لَهُمَا: اُطْلُبِ الْعِلْمَ مَا حَيِيتَ وَتَوَاضَعْ لِلَّهِ مَا بَقِيتَ", "segs": [{"ar": "اِسْمَعْ يَا بُنَيَّ يَجِبُ أَنْ تَضَعَ نُصْبَ عَيْنَيْكَ أَمْرَيْنِ اثْنَيْنِ لَا ثَالِثَ لَهُمَا", "uz": "eshit, o'g'lim, ko'z oldingda ikkita — uchinchisi bo'lmagan — narsani tutishing kerak"}, {"ar": "اُطْلُبِ الْعِلْمَ مَا حَيِيتَ وَتَوَاضَعْ لِلَّهِ مَا بَقِيتَ", "uz": "hayoting davomida ilm izla va umring boricha Allohga kamtarlik qil"}], "full_uz": "Eshit, o'g'lim, ko'z oldingda ikkita — uchinchisi bo'lmagan — narsani tutishing kerak: hayoting davomida ilm izla va umring boricha Allohga kamtarlik qil.", "note": null},
  {"num": 401, "time": "00:23:31,000 --> 00:23:36,000", "arabic": "زُمُرُّدَةُ، أَخْشَى أَنْ تَمْرَضَ الْفَتَاةُ إِنْ مَنَعْنَاهَا الطَّعَامَ أَكْثَرَ مِنْ ذَلِكَ", "segs": null, "full_uz": "Zumurrad, agar qizni ovqatdan bundan ham ko'p mahrum qilsak, kasal bo'lib qolishidan qo'rqaman.", "note": null},
  {"num": 402, "time": "00:23:36,000 --> 00:23:42,000", "arabic": "فَلْتَذْهَبْ إِلَى الْجَحِيمِ، أُقْسِمُ إِنَّهَا لَنْ تَذُوقَ لُقْمَةً مِنْ طَعَامٍ وَلَا شَرَابٍ حَتَّى تَلِينَ رَأْسَهَا وَتَتْرُكَ عِنَادَهَا", "segs": null, "full_uz": "Do'zaxga tushsin, qasam ichamanki, boshi yumshab, qaysarligini tashlaguncha bir luqma taom yoki bir tomchi suv totmaydi.", "note": null},
  {"num": 405, "time": "00:23:42,000 --> 00:23:48,000", "arabic": "وَلَكِنَّهَا كَنْزٌ لَا يَنْبَغِي عَلَيْنَا أَنْ نُغَامِرَ بِخَسَارَتِهِ، وَمَا فَائِدَةُ هَذَا الْكَنْزِ إِنْ كُنَّا لَا نَسْتَطِيعُ بَيْعَهُ؟", "segs": null, "full_uz": "Lekin u — biz undan mahrum bo'lishga jur'at eta olmaydigan xazina, va agar sotolmasak, bu xazinadan foyda nima?", "note": null},
  {"num": 407, "time": "00:23:48,000 --> 00:23:54,000", "arabic": "لَقَدْ عَيِلَ صَبْرِي وَسَوْفَ نَرَى مَنْ أَعْنَتُ، أَنَا أَمْ أَنْتَ يَا فَوْزُ", "segs": null, "full_uz": "Sabrim tugadi, va kim qattiqroq turishini ko'ramiz — men yoki sen, Favz.", "note": null},
  {"num": 409, "time": "00:23:54,000 --> 00:23:59,000", "arabic": "أَنْتَ أَدْرَى يَا زُمُرُّدَةُ، وَالرَّأْيُ أَنْ لَا نَقْسُوَ عَلَيْهَا أَكْثَرَ مِنْ بَابِ الرَّحْمَةِ لَيْسَ إِلَّا", "segs": null, "full_uz": "Sen bilasan, Zumurrad, mening fikrim — unga bundan ortiq qattiqqo'llik qilmaslik, faqat shafqatdan.", "note": null},
  {"num": 412, "time": "00:23:59,000 --> 00:24:03,000", "arabic": "وَأَيْضًا كَيْ لَا تَفْقِدَ جَمَالَهَا فَيَقِلَّ سِعْرُهَا", "segs": null, "full_uz": "Va bundan tashqari, go'zalligini yo'qotib, narxi tushib ketmasligi uchun ham.", "note": null},
  {"num": 413, "time": "00:24:03,000 --> 00:24:08,000", "arabic": "لَمْ يَعُدْ يَهُمُّنِي لَا لَا، لَمْ يَعُدْ يَهُمُّنِي أَنْ أَبِيعَهَا أَمْ لَا", "segs": null, "full_uz": "Endi meni qiziqtirmaydi, yo'q, yo'q, uni sotaman-sotmaymanmi — endi meni qiziqtirmaydi.", "note": null},
  {"num": 416, "time": "00:24:08,000 --> 00:24:13,000", "arabic": "اَلْمُهِمُّ عِنْدِي أَنْ أُذِلَّهَا وَأَكْسِرَ رَأْسَهَا وَأُعِيدَ تَرْبِيَتَهَا مِنْ جَدِيدٍ", "segs": null, "full_uz": "Muhimi — uni xo'rlashim, qat'iyatini sindirishim va uni yangidan tarbiyalashim.", "note": null},
  {"num": 420, "time": "00:24:31,000 --> 00:24:36,000", "arabic": "أَحْسَنْتَ، إِنَّهُ عَمَلٌ رَائِعٌ، اَلْحَمْدُ لِلَّهِ أَنَّهُ حَازَ فَضْلَ اسْتِحْسَانِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Barakalla, bu ajoyib ish. Alhamdulillah, u sizning maqtovingizga sazovor bo'ldi, xo'jayinim.", "note": null},
  {"num": 423, "time": "00:24:36,000 --> 00:24:41,000", "arabic": "بَلْ نَالَ إِعْجَابِي، شَهَادَتُكَ تَاجٌ عَلَى رَأْسِ عَبْدِكَ الْفَقِيرِ وَخَادِمِكَ الْوَفِيِّ الْأَمِينِ", "segs": null, "full_uz": "Balki hayratimga sazovor bo'ldi. Sizning guvohligingiz — kambag'al bandangiz va sodiq xizmatkoringizning boshidagi tojdir.", "note": null},
  {"num": 426, "time": "00:24:41,000 --> 00:24:46,000", "arabic": "اِسْمَعْ أَيُّهَا الْفَتَى، كُنْ قَرِيبًا مِنِّي، فَمُهِمَّةٌ خَطِيرَةٌ تَنْتَظِرُكَ", "segs": null, "full_uz": "Eshit, yigit, menga yaqin bo'l, chunki seni og'ir bir vazifa kutmoqda.", "note": null},
  {"num": 429, "time": "00:24:46,000 --> 00:24:50,000", "arabic": "أَنَا طَوْعُ بَنَانِكَ وَرَهْنُ إِشَارَتِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Men sizning har bir buyrug'ingizga to'la itoatdaman, xo'jayinim.", "note": null},
  {"num": 430, "time": "00:24:50,000 --> 00:24:53,000", "arabic": "اِنْتَظِرْ هُنَا الْآنَ", "segs": null, "full_uz": "Hozir shu yerda kut.", "note": null},
  {"num": 431, "time": "00:24:53,000 --> 00:24:55,000", "arabic": "أَمْرُكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Amringiz bajo, xo'jayinim.", "note": null},
  {"num": 432, "time": "00:24:55,000 --> 00:24:58,000", "arabic": "سَيَكُونُ لِهَذَا الْفَتَى شَأْنٌ كَبِيرٌ", "segs": null, "full_uz": "Bu yigitning kelajagi porloq bo'ladi.", "note": null},
  {"num": 433, "time": "00:25:01,000 --> 00:25:05,000", "arabic": "أَتَرَاهُ مُنَاسِبًا لِمَا عَقَدْتَ الْعَزْمَ عَلَيْهِ يَا أَبِي؟", "segs": null, "full_uz": "Uni qat'iy niyat qilgan ishingiz uchun mos deb bilasizmi, otajon?", "note": null},
  {"num": 434, "time": "00:25:05,000 --> 00:25:08,000", "arabic": "هُوَ تَمَامًا مَا نُرِيدُ", "segs": null, "full_uz": "U aynan biz xohlagan kishi.", "note": null},
  {"num": 435, "time": "00:25:08,000 --> 00:25:11,000", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 436, "time": "00:25:11,000 --> 00:25:14,000", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga ham salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 437, "time": "00:25:14,000 --> 00:25:19,000", "arabic": "سَوْفَ أُفَاتِحُ الرَّشِيدَ غَدًا بِأَمْرِ إِيكَالِ رِعَايَةِ الْأَمِينِ إِلَيْكَ", "segs": null, "full_uz": "Ertaga ar-Rashidga Aminning tarbiyasini sizga topshirish masalasida gap ochaman.", "note": null},
  {"num": 438, "time": "00:25:19,000 --> 00:25:21,000", "arabic": "وَالْمَأْمُونُ؟", "segs": null, "full_uz": "Ma'mun-chi?", "note": null},
  {"num": 440, "time": "00:25:21,000 --> 00:25:24,000", "arabic": "دَعْنَا مِنَ الْمَأْمُونِ الْآنَ", "segs": null, "full_uz": "Ma'munni hozircha qo'yib tur.", "note": null},
  {"num": 441, "time": "00:25:24,000 --> 00:25:28,000", "arabic": "وَلِمَ التَّأْجِيلُ يَا أَبِي؟ لِمَ التَّأْجِيلُ؟", "segs": null, "full_uz": "Nega kechiktirasiz, otajon? Nega kechiktirasiz?", "note": null},
  {"num": 443, "time": "00:25:28,000 --> 00:25:35,000", "arabic": "أَلَيْسَ مِنَ الْأَفْضَلِ أَنْ تَطْرَحَ الْمَسْأَلَةَ عَلَى الرَّشِيدِ مَرَّةً وَاحِدَةً، أَنْ يَكُونَ الْفَضْلُ وَصِيًّا عَلَى الْأَمِينِ", "segs": null, "full_uz": "Masalani ar-Rashidga bir yo'la, Fadl Aminga vasiy bo'lsin, deb qo'ymaslik yaxshiroq emasmi?", "note": null},
  {"num": 445, "time": "00:25:35,000 --> 00:25:39,000", "arabic": "وَكَذَلِكَ مَنْ تَرَاهُ مُنَاسِبًا لِيَكُونَ وَصِيًّا عَلَى الْمَأْمُونِ", "segs": null, "full_uz": "Va shuningdek, Ma'munga vasiy bo'lishga kimni mos deb bilasiz?", "note": null},
  {"num": 446, "time": "00:25:39,000 --> 00:25:43,000", "arabic": "هَارُونُ رَجُلٌ ذَكِيٌّ وَلَا أُرِيدُ أَنْ أُثِيرَ شُكُوكَهُ", "segs": null, "full_uz": "Horun aqlli odam, va uning shubhasini uyg'otishni istamayman.", "note": null},
  {"num": 448, "time": "00:25:43,000 --> 00:25:47,000", "arabic": "لَا تُقْطَفُ الثَّمَرَةُ قَبْلَ نُضْجِهَا فَتُحْرَمَ", "segs": null, "full_uz": "Meva pishmasdan uzilmaydi, aks holda undan mahrum bo'lasan.", "note": "Vaqtidan oldin shoshilib ish qilishning zararli oqibatlarini bildiruvchi hikmatli-majoziy gap."},
  {"num": 449, "time": "00:25:47,000 --> 00:25:52,000", "arabic": "أَخْشَى يَا أَبِي إِنْ لَمْ تُسَارِعْ فِي طَرْحِ أَمْرِ الْمَأْمُونِ أَنْ تُفْلِتَ وِصَايَتُهُ مِنْ أَيْدِينَا", "segs": null, "full_uz": "Qo'rqamanki, otajon, agar Ma'mun masalasini shoshilmasangiz, uning vasiyligi qo'limizdan chiqib ketadi.", "note": null},
  {"num": 450, "time": "00:25:52,000 --> 00:25:57,000", "arabic": "أَرَى أَنَّ أَبَاكَ عَلَى حَقٍّ يَا جَعْفَرُ، لَا يَنْبَغِي التَّهَوُّرُ فِي مَسْأَلَةٍ خَطِيرَةٍ كَهَذِهِ", "segs": null, "full_uz": "Otangiz haq deb bilaman, Ja'far, bunday og'ir masalada shoshqaloqlik qilmaslik kerak.", "note": null},
  {"num": 452, "time": "00:26:01,000 --> 00:26:05,000", "arabic": "مَا لِي أَرَاكَ مَشْغُولَ الْبَالِ يَا وَلَدِي؟", "segs": null, "full_uz": "Nega seni g'amga botgan ko'ryapman, o'g'lim?", "note": null},
  {"num": 453, "time": "00:26:05,000 --> 00:26:07,000", "arabic": "بِشَيْءٍ يَا أُمِّي لَا شَيْءَ", "segs": null, "full_uz": "Bir narsa, onajon, hech narsa emas.", "note": null},
  {"num": 454, "time": "00:26:07,000 --> 00:26:11,000", "arabic": "أَنْتَ لَا تَكُفُّ عَنِ التَّفْكِيرِ، وَقَلْبِي يُخْبِرُنِي أَنَّ أَمْرًا مَا يَشْغَلُكَ", "segs": null, "full_uz": "Sen o'ylashdan to'xtamaysan, va yuragim menga senga tashvish bergan narsa borligini aytmoqda.", "note": null},
  {"num": 456, "time": "00:26:11,000 --> 00:26:15,000", "arabic": "أَنْتَ لَسْتَ رَاضِيًا عَنْ ذَهَابِكَ لِحَلْقَةِ الْإِمَامِ أَبِي يُوسُفَ", "segs": null, "full_uz": "Imom Abu Yusuf halqasiga borishingdan rozi emassan.", "note": null},
  {"num": 457, "time": "00:26:15,000 --> 00:26:18,000", "arabic": "حَلْقَةُ الْإِمَامِ أَبِي يُوسُفَ نُورٌ مِنَ السَّمَاءِ يَا أُمِّي، وَلَكِنْ", "segs": null, "full_uz": "Imom Abu Yusuf halqasi osmondan tushgan nur, onajon, lekin...", "note": null},
  {"num": 459, "time": "00:26:18,000 --> 00:26:20,000", "arabic": "وَلَكِنْ مَاذَا يَا بُنَيَّ؟", "segs": null, "full_uz": "Lekin nima, o'g'lim?", "note": null},
  {"num": 460, "time": "00:26:20,000 --> 00:26:23,000", "arabic": "لَدَيَّ طُمُوحٌ لَمْ أَبْلُغْهُ فِي حَلْقَةِ الْإِمَامِ أَبِي يُوسُفَ", "segs": null, "full_uz": "Menda imom Abu Yusuf halqasida yetolmagan bir orzu bor.", "note": null},
  {"num": 461, "time": "00:26:23,000 --> 00:26:26,000", "arabic": "وَهَذَا مَا حَدَّثَنِي بِهِ قَلْبِي يَا بُنَيَّ", "segs": null, "full_uz": "Yuragim ham menga shuni aytgan edi, o'g'lim.", "note": null},
  {"num": 462, "time": "00:26:26,000 --> 00:26:31,000", "arabic": "أَدْرَكْتُ أَنَّ مَا تَصْبُو إِلَيْهِ لَمْ تَجِدْهُ فِي حَلْقَةِ دَرْسِ أَبِي يُوسُفَ", "segs": null, "full_uz": "Intilgan narsangni Abu Yusuf dars halqasida topolmaganingni angladim.", "note": null},
  {"num": 464, "time": "00:26:31,000 --> 00:26:35,000", "arabic": "صَدَقَ حَدْسُكِ يَا أُمَّ أَحْمَدَ، وَلَكِنْ إِلَى الْآنَ لَمْ تَقُولِي لِي مَا هُوَ رَأْيُكِ فِيمَا أُفَكِّرُ", "segs": null, "full_uz": "Sezgingiz to'g'ri, Umm Ahmad, lekin hali menga o'ylayotgan narsam haqida fikringizni aytmadingiz.", "note": null},
  {"num": 466, "time": "00:26:35,000 --> 00:26:41,000", "arabic": "قُمْ يَا بُنَيَّ، تَوَضَّأْ وَصَلِّ رَكْعَتَيْنِ وَاسْتَخِرْ رَبَّكَ فِيمَا نَوَيْتَ وَأَخْلِصْ لَهُ نِيَّتَكَ", "segs": [{"ar": "قُمْ يَا بُنَيَّ، تَوَضَّأْ وَصَلِّ رَكْعَتَيْنِ", "uz": "tur, o'g'lim, tahorat ol va ikki rakat namoz o'qi"}, {"ar": "وَاسْتَخِرْ رَبَّكَ فِيمَا نَوَيْتَ وَأَخْلِصْ لَهُ نِيَّتَكَ", "uz": "va niyat qilgan ishingda Robbingdan istixora so'ra, va niyatingni Unga xolis qil"}], "full_uz": "Tur, o'g'lim, tahorat ol va ikki rakat namoz o'qi, va niyat qilgan ishingda Robbingdan istixora so'ra, va niyatingni Unga xolis qil.", "note": "«اِسْتِخَارَةُ» — biror muhim ishga qaror qilishdan oldin Allohdan yo'l-yo'riq so'rab o'qiladigan maxsus ikki rakat namoz."},
  {"num": 471, "time": "00:26:41,000 --> 00:26:47,000", "arabic": "وَاعْلَمْ يَا بُنَيَّ أَنَّ اللَّهَ فِي عَوْنِ عَبْدِهِ طَالَمَا هَذَا الْعَبْدُ يَسِيرُ عَلَى هَدْيِهِ وَهَدْيِ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Va bilib qo'y, o'g'lim, Alloh bandasi Uning va payg'ambari yo'lida yurar ekan, unga doim yordamchidir.", "note": null},
  {"num": 475, "time": "00:27:01,000 --> 00:27:06,000", "arabic": "لَيْسَ لِي إِلَّا حَلْقَةُ الْإِمَامِ أَبِي مُعَاوِيَةَ", "segs": null, "full_uz": "Menga faqat imom Abu Mu'oviya halqasigina qoladi.", "note": null},
  {"num": 476, "time": "00:27:06,000 --> 00:27:10,000", "arabic": "هُوَ ذَاكَ يَا أَحْمَدُ، نِعْمَ الرَّأْيُ وَحُسْنُ الِاخْتِيَارِ", "segs": null, "full_uz": "Aynan shu, Ahmad, qanday go'zal fikr va yaxshi tanlov.", "note": null},
  {"num": 477, "time": "00:27:10,000 --> 00:27:12,000", "arabic": "هَلْ سَتَذْهَبُ مَعِي؟", "segs": null, "full_uz": "Men bilan borasanmi?", "note": null},
  {"num": 478, "time": "00:27:12,000 --> 00:27:16,000", "arabic": "اَلتَّفَرُّغُ لِطَلَبِ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْرٌ لَا يَحْتَمِلُ الرَّفْضَ", "segs": null, "full_uz": "Rasululloh hadislarini o'rganishga bag'ishlanish rad etib bo'lmaydigan ishdir.", "note": null},
  {"num": 479, "time": "00:27:16,000 --> 00:27:20,000", "arabic": "وَلَكِنْ مَاذَا عَنْكَ أَنْتَ؟ هَلْ حَسَمْتَ أَمْرَكَ؟", "segs": null, "full_uz": "Lekin sen-chi? Ishingga qat'iy qaror qildingmi?", "note": null},
  {"num": 480, "time": "00:27:20,000 --> 00:27:24,000", "arabic": "قُلْتُ لَكَ أَنَّ أُمِّي هِيَ مَنْ نَصَحَتْنِي بِذَلِكَ، وَتَعْلَمُ كَمْ أَثِقُ بِرَأْيِهَا", "segs": null, "full_uz": "Senga aytdim-ku, onam meni shunga nasihat qilgan, va bilasan, uning fikriga qanchalik ishonaman.", "note": null},
  {"num": 481, "time": "00:27:24,000 --> 00:27:28,000", "arabic": "وَصُحْبَتُكَ هِيَ سَعَادَتِي يَا مُحَمَّدُ، مَاذَا قُلْتَ؟", "segs": null, "full_uz": "Sening hamrohliging mening baxtim, Muhammad. Nima dedingiz?", "note": null},
  {"num": 482, "time": "00:27:28,000 --> 00:27:33,000", "arabic": "كَيْفَ لِي أَنْ لَا أُجِيبَ مَا دَعَتْ إِلَيْهِ أُمُّ أَحْمَدَ وَمَا عَزَمَ عَلَيْهِ رَفِيقُ دَرْبِ أَحْمَدَ بْنِ حَنْبَلٍ", "segs": null, "full_uz": "Umm Ahmad chorlagan ishga, va Ahmad ibn Hanbalning yo'ldoshi qaror qilgan ishga qanday javob bermay?", "note": null},
  {"num": 484, "time": "00:27:33,000 --> 00:27:37,000", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا صَاحِبِي", "segs": null, "full_uz": "Alloh senga baraka bersin, do'stim.", "note": null},
  {"num": 485, "time": "00:27:37,000 --> 00:27:40,000", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 486, "time": "00:28:01,000 --> 00:28:04,000", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 487, "time": "00:28:04,000 --> 00:28:07,000", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 488, "time": "00:28:07,000 --> 00:28:10,000", "arabic": "أَهْلًا بِأُمِّ خَالِدٍ أَهْلًا بِضَيْفَتِنَا شَهْنَازَ", "segs": null, "full_uz": "Xush kelibsiz, Umm Xolid, xush kelibsan, mehmonimiz Shahnoz.", "note": null},
  {"num": 489, "time": "00:28:10,000 --> 00:28:14,000", "arabic": "كُنَّا فِي السُّوقِ نَشْتَرِي بَعْضَ حَاجَاتِ الْبَيْتِ فَقُلْنَا نَعْرُجُ عَلَيْكِ قَبْلَ أَنْ نَعُودَ", "segs": null, "full_uz": "Bozorda uy ehtiyojlarini xarid qilib yurgan edik, qaytishdan oldin senga o'tib ketaylik dedik.", "note": null},
  {"num": 491, "time": "00:28:14,000 --> 00:28:20,000", "arabic": "غَفَرَ اللَّهُ لِأُمِّ خَالِدٍ، لِمَ لَمْ تُخْبِرِينِي فِي الصَّبَاحِ بِمَا تَحْتَاجِينَهُ حَتَّى آتِيَكِ الْبَيْتَ؟", "segs": null, "full_uz": "Alloh Umm Xolidni kechirsin, nega ertalab menga nima kerakligini aytmading, senga uyingga olib borardim?", "note": null},
  {"num": 493, "time": "00:28:20,000 --> 00:28:23,000", "arabic": "قَاتَلَ اللَّهُ التَّرَدُّدَ", "segs": null, "full_uz": "Ikkilanish la'natlansin.", "note": null},
  {"num": 494, "time": "00:28:23,000 --> 00:28:27,000", "arabic": "يَبْدُو أَنَّ اللَّهَ أَرْسَلَ لِي هَذِهِ الْفَتَاةَ لِتَكُونَ سَبَبَ سَعْدِي", "segs": null, "full_uz": "Shekilli, Alloh menga bu qizni baxtimga sabab bo'lsin deb yubordi.", "note": null},
  {"num": 496, "time": "00:28:31,000 --> 00:28:35,000", "arabic": "لَوْ أَعْرِفُ كَيْفَ يَجِدُ ابْنُ حَنْبَلٍ الْوَقْتَ لِيَسْتَظْهِرَ دُرُوسَهُ وَيُعِيدَهَا أَمَامَ شَيْخِنَا أَبِي يُوسُفَ", "segs": null, "full_uz": "Qani edi, Ibn Hanbal darslarini yodlab, shayximiz Abu Yusuf oldida qaytarishga qanday vaqt topayotganini bilsam.", "note": null},
  {"num": 498, "time": "00:28:35,000 --> 00:28:40,000", "arabic": "مَا بَالُكَ أَيُّهَا الْأَحْمَقُ، أَتُرِيدُ أَنْ تُفْسِدَ عَلَيْنَا نُزْهَتَنَا هَذِهِ بِذِكْرِكَ لِابْنِ حَنْبَلٍ؟", "segs": null, "full_uz": "Senga nima bo'ldi, ey ahmoq, Ibn Hanbalni tilga olib, bu sayrimizni buzmoqchimisan?", "note": null},
  {"num": 499, "time": "00:28:40,000 --> 00:28:43,000", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 500, "time": "00:28:43,000 --> 00:28:45,000", "arabic": "عَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Sizga ham salom.", "note": null},
  {"num": 501, "time": "00:28:45,000 --> 00:28:49,000", "arabic": "لَوْ تَعْلَمُ مَاذَا أَحْمِلُ لَكَ مِنْ أَخْبَارٍ يَا صُهَيْبُ", "segs": null, "full_uz": "Sen bilsang edi, senga qanday xabar olib kelayotganimni, Suhayb.", "note": null},
  {"num": 502, "time": "00:28:49,000 --> 00:28:51,000", "arabic": "أَفْصِحْ، مَاذَا هُنَاكَ؟", "segs": null, "full_uz": "Ayt, nima gap?", "note": null},
  {"num": 503, "time": "00:28:51,000 --> 00:28:57,000", "arabic": "لَقَدْ سَمِعْتُ ابْنَ حَنْبَلٍ يَقُولُ لِابْنِ نُوحٍ بِأَنَّهُ سَيَلْتَحِقُ بِحَلَقَاتِ الْإِمَامِ هُشَيْمِ بْنِ بَشِيرٍ الْوَاسِطِيِّ", "segs": null, "full_uz": "Ibn Hanbalning Ibn Nuhga imom Hushaym ibn Bashir al-Vositiy halqalariga qo'shilaman deganini eshitdim.", "note": null},
  {"num": 504, "time": "00:28:57,000 --> 00:29:00,000", "arabic": "يَا لَمُفَاجَآتِكَ يَا ابْنَ حَنْبَلٍ، قَرَارَاتُهُ مَدْرُوسَةٌ وَخُطُوَاتُهُ مَحْسُوبَةٌ", "segs": null, "full_uz": "Voajab, sening qarorlaring o'ylab qilingan va qadamlaring hisoblangan, Ibn Hanbal-a.", "note": null},
  {"num": 506, "time": "00:29:00,000 --> 00:29:04,000", "arabic": "هَذِهِ الْمَرَّةَ أَنَا مَنْ سَيُفَاجِئُهُ إِذَنْ", "segs": null, "full_uz": "Bu safar, unda, uni hayratda qoldiradigan men bo'laman.", "note": null},
  {"num": 507, "time": "00:29:31,000 --> 00:29:35,000", "arabic": "كُنْتُ أَوَدُّ أَنْ أَعْرِضَ أَمْرًا عَلَى مَوْلَايَ الرَّشِيدِ", "segs": null, "full_uz": "Xo'jayinim ar-Rashidga bir masalani taklif qilmoqchi edim.", "note": null},
  {"num": 508, "time": "00:29:35,000 --> 00:29:38,000", "arabic": "قُلْ يَا يَحْيَى إِنِّي أَسْمَعُكَ", "segs": null, "full_uz": "Ayt, Yahyo, seni tinglayapman.", "note": null},
  {"num": 509, "time": "00:29:38,000 --> 00:29:40,000", "arabic": "اَلْأَمِيرُ الْأَمِينُ وَلَدُكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Amir Amin — sizning o'g'lingiz, xo'jayinim.", "note": null},
  {"num": 510, "time": "00:29:40,000 --> 00:29:41,000", "arabic": "مَا بِهِ؟", "segs": null, "full_uz": "Unga nima bo'ldi?", "note": null},
  {"num": 511, "time": "00:29:41,000 --> 00:29:48,000", "arabic": "أَرَى يُسْنِدُ مَوْلَايَ الرَّشِيدُ أَمْرَ رِعَايَتِهِ إِلَى مَنْ يَثِقُ بِهِ وَيَمْنَحُهُ مِنَ الْوَقْتِ وَالِاهْتِمَامِ بِمَا لَمْ تَسْمَحْ بِهِ الظُّرُوفُ لِمَوْلَايَ الرَّشِيدِ بِمِثْلِهِمَا", "segs": [{"ar": "أَرَى يُسْنِدُ مَوْلَايَ الرَّشِيدُ أَمْرَ رِعَايَتِهِ إِلَى مَنْ يَثِقُ بِهِ", "uz": "xo'jayinim ar-Rashid uning tarbiyasini ishonadigan kishiga topshirishini istardim"}, {"ar": "وَيَمْنَحُهُ مِنَ الْوَقْتِ وَالِاهْتِمَامِ بِمَا لَمْ تَسْمَحْ بِهِ الظُّرُوفُ لِمَوْلَايَ الرَّشِيدِ بِمِثْلِهِمَا", "uz": "va sharoit tufayli sizga yetmagan vaqt va e'tiborni unga bag'ishlaydigan kishiga"}], "full_uz": "Xo'jayinim ar-Rashid uning tarbiyasini, sharoit tufayli sizga yetmagan vaqt va e'tiborni bag'ishlay oladigan, ishonadigan kishiga topshirishini istardim.", "note": null},
  {"num": 515, "time": "00:29:48,000 --> 00:29:52,000", "arabic": "أَصَبْتَ الرَّأْيَ يَا يَحْيَى، لَقَدْ كَانَ ذَلِكَ يَدُورُ فِي خَلَدِي مُنْذُ أَمَدٍ لَيْسَ بِبَعِيدٍ", "segs": null, "full_uz": "To'g'ri fikrladingiz, Yahyo, bu ancha vaqtdan beri xayolimda aylanib yurgan edi.", "note": null},
  {"num": 517, "time": "00:29:52,000 --> 00:29:57,000", "arabic": "وَلَكِنَّنِي حَائِرٌ إِلَى مَنْ أُوَكِّلُ أَمْرَهُ إِلَى مَنْ يَثِقُ بِهِ مَوْلَايَ وَيَجِدُهُ أَهْلًا لِذَلِكَ", "segs": null, "full_uz": "Lekin bu ishni kimga topshirishni bilmay hayronman, xo'jayinim ishonadigan va bunga munosib deb bilgan kimsaga.", "note": null},
  {"num": 519, "time": "00:29:57,000 --> 00:29:59,000", "arabic": "وَمَنْ يَكُونُ يَا يَحْيَى؟", "segs": null, "full_uz": "Kim bo'lardi, Yahyo?", "note": null},
  {"num": 520, "time": "00:30:01,000 --> 00:30:06,000", "arabic": "مَا رَأْيُكَ يَا مَوْلَايَ فِي الْفَضْلِ ابْنِ يَحْيَى الْبَرْمَكِيِّ", "segs": null, "full_uz": "Fadl ibn Yahyo al-Barmakiy haqida nima deysiz, xo'jayinim.", "note": null},
  {"num": 522, "time": "00:30:06,000 --> 00:30:10,000", "arabic": "أَخُو مَوْلَايَ الرَّشِيدِ فِي الرَّضَاعَةِ وَابْنُ خَادِمِيَ الْمُخْلِصِ", "segs": null, "full_uz": "Xo'jayinim ar-Rashidning emikdosh birodari va mening sodiq xizmatkorimning o'g'li.", "note": null},
  {"num": 524, "time": "00:30:10,000 --> 00:30:15,000", "arabic": "نِعْمَ الِاخْتِيَارُ يَا يَحْيَى، نِعْمَ الِاخْتِيَارُ، وَالْفَضْلُ فِي خِدْمَةِ مَوْلَايَ الرَّشِيدِ وَخِدْمَةِ ابْنِهِ الْأَمِينِ", "segs": null, "full_uz": "Ajoyib tanlov, Yahyo, ajoyib tanlov, va Fadl xo'jayinim ar-Rashidga hamda uning o'g'li Aminga xizmat qilishga tayyor.", "note": null},
  {"num": 528, "time": "00:30:31,000 --> 00:30:34,000", "arabic": "لَقَدِ انْتَهَيْتُ، اُنْظُرْ", "segs": null, "full_uz": "Tugatdim, qarang.", "note": null},
  {"num": 530, "time": "00:30:34,000 --> 00:30:38,000", "arabic": "وَالْآنَ كَيْفَ رَضِيَ الْمُعَلِّمُ عَنْ تِلْمِيذِهِ يَا فَرَجُ؟", "segs": null, "full_uz": "Xo'sh, ustoz shogirdidan roziymi, Faraj?", "note": null},
  {"num": 531, "time": "00:30:38,000 --> 00:30:41,000", "arabic": "أَخْشَى أَنْ يَغُرَّكَ ثَنَائِي فَتَكْسَلَ يَا فَرَجُ", "segs": null, "full_uz": "Qo'rqamanki, maqtovim seni g'ururlantirib, dangasa qilib qo'yadi, Faraj.", "note": null},
  {"num": 532, "time": "00:30:41,000 --> 00:30:45,000", "arabic": "لَا يَا سَيِّدِي لَا، فَأَنَا حَرِيصٌ عَلَى عَمَلِي حِرْصِي عَلَى حَيَاتِي", "segs": null, "full_uz": "Yo'q, hazratim, yo'q, men ishimga hayotimga bo'lgan g'amxo'rligim kabi g'amxo'rlik qilaman.", "note": null},
  {"num": 533, "time": "00:30:45,000 --> 00:30:50,000", "arabic": "إِنْ بَقِيتَ عَلَى جِدِّكَ وَإِخْلَاصِكَ فَسَتَكُونُ بِمَثَابَةِ ابْنِي", "segs": null, "full_uz": "Agar jiddiyligingda va sadoqatingda davom etsang, mening o'g'lim kabi bo'lasan.", "note": null},
  {"num": 534, "time": "00:30:50,000 --> 00:30:52,000", "arabic": "آهِ يَا مُعَلِّمِي آهِ", "segs": null, "full_uz": "Oh, ustozim, oh.", "note": null},
  {"num": 535, "time": "00:30:52,000 --> 00:30:55,000", "arabic": "وَلِمَ هَذِهِ الْحُرْقَةُ يَا فَرَجُ؟", "segs": null, "full_uz": "Bu achchiq iztirob nimadan, Faraj?", "note": null},
  {"num": 536, "time": "00:30:55,000 --> 00:31:00,000", "arabic": "لَقَدْ عِشْتُ فِي دُنْيَايَ يَتِيمًا دُونَ أَبٍ، فَقِيرًا دُونَ مُعِيلٍ", "segs": null, "full_uz": "Bu dunyoda otasiz yetim, boquvchisiz kambag'al bo'lib yashadim.", "note": null},
  {"num": 538, "time": "00:31:00,000 --> 00:31:06,000", "arabic": "وَلَكِنْ دَخَلْتُ دُكَّانَكَ وَأَنَا أَحْلُمُ أَنْ أَتْرُكَ مَاضِيَ الْبَائِسَ وَرَاءَ ظَهْرِي", "segs": null, "full_uz": "Lekin do'koningizga kirganimda, achinarli o'tmishimni ortda qoldirishni orzu qilardim.", "note": null},
  {"num": 541, "time": "00:31:06,000 --> 00:31:12,000", "arabic": "بِالْجِدِّ وَالْمُثَابَرَةِ يَنَالُ الْمَرْءُ بُغْيَتَهُ، فَلَا تَعْجَلْ لَهَا، مَا زِلْتَ فِي مُقْتَبَلِ الْعُمْرِ وَأَمَامَكَ الدَّرْبُ طَوِيلٌ", "segs": [{"ar": "بِالْجِدِّ وَالْمُثَابَرَةِ يَنَالُ الْمَرْءُ بُغْيَتَهُ", "uz": "jiddiylik va matonat bilan inson maqsadiga yetadi"}, {"ar": "فَلَا تَعْجَلْ لَهَا، مَا زِلْتَ فِي مُقْتَبَلِ الْعُمْرِ وَأَمَامَكَ الدَّرْبُ طَوِيلٌ", "uz": "shoshilma, sen hali yoshsan va oldingda uzoq yo'l bor"}], "full_uz": "Jiddiylik va matonat bilan inson maqsadiga yetadi, shoshilma, sen hali yoshsan va oldingda uzoq yo'l bor.", "note": null},
  {"num": 546, "time": "00:31:12,000 --> 00:31:17,000", "arabic": "أَتَحْسَبُ أَنَّكَ وَحْدَكَ مَنْ عَانَى الْبُؤْسَ وَالْمُعَانَاةَ؟ لَقَدْ عَانَيْتُ أَكْثَرَ مِنْ ذَلِكَ بِكَثِيرٍ حَتَّى وَصَلْتُ إِلَى مَا أَنَا عَلَيْهِ، حَتَّى شَقَقْتُ فِي بَطْنِ الصَّخْرِ", "segs": [{"ar": "أَتَحْسَبُ أَنَّكَ وَحْدَكَ مَنْ عَانَى الْبُؤْسَ وَالْمُعَانَاةَ؟", "uz": "faqat sengina achchiq kunlarni ko'rgan deb o'ylaysanmi?"}, {"ar": "لَقَدْ عَانَيْتُ أَكْثَرَ مِنْ ذَلِكَ بِكَثِيرٍ حَتَّى وَصَلْتُ إِلَى مَا أَنَا عَلَيْهِ", "uz": "men hozirgi holatimga yetgunimcha bundan ancha ko'proq azob chekdim"}, {"ar": "حَتَّى شَقَقْتُ فِي بَطْنِ الصَّخْرِ", "uz": "hatto qattiq tosh ichida yo'l ochishga to'g'ri keldi"}], "full_uz": "Faqat sengina achchiq kunlarni ko'rgan deb o'ylaysanmi? Men hozirgi holatimga yetgunimcha bundan ancha ko'proq azob chekdim, hatto qattiq tosh ichida yo'l ochishga to'g'ri keldi.", "note": "«شَقَّ فِي بَطْنِ الصَّخْرِ» — «tosh ichida yo'l yormoq», ya'ni juda katta qiyinchiliklarni yengib o'tish ma'nosidagi majoziy ibora."},
  {"num": 550, "time": "00:31:17,000 --> 00:31:20,000", "arabic": "وَلَكِنْ مَنْ أَحْسَنَ الْغَرْسَ أَحْسَنَ اللَّهُ الْعَطَاءَ", "segs": null, "full_uz": "Lekin kim yaxshi eksa, Alloh unga yaxshi hosil beradi.", "note": null},
  {"num": 551, "time": "00:31:20,000 --> 00:31:26,000", "arabic": "سَيِّدِي أَنَا أَحْلُمُ أَنْ أَكُونَ مِنْ كِبَارِ سَادَةِ بَغْدَادَ، أَنْ يَكُونَ لِي قَصْرٌ كَقُصُورِ الْبَرَامِكَةِ", "segs": null, "full_uz": "Hazratim, men Bag'dodning katta zodagonlaridan biri bo'lishni, Barmaklar saroylaridek saroyim bo'lishini orzu qilaman.", "note": null},
  {"num": 553, "time": "00:31:26,000 --> 00:31:31,000", "arabic": "ضِيَاعٌ كَثِيرَةٌ، زَوْجَةٌ وَأَوْلَادٌ، وَأَنْ تَذُوقَ أُمِّي الْهَنَاءَةَ وَالرَّاحَةَ بَعْدَ الْبُؤْسِ وَالتَّعَبِ", "segs": null, "full_uz": "Ko'plab yer-mulklar, xotin va farzandlar, va onam bu tashvish va charchoqdan keyin farovonlik va tinchlikni totishi.", "note": null},
  {"num": 555, "time": "00:31:31,000 --> 00:31:34,000", "arabic": "لَكِنَّ هَذَا لَا يَبْدُو إِلَّا أَضْغَاثَ أَحْلَامٍ", "segs": null, "full_uz": "Lekin bu faqat parishon tush kabi ko'rinadi.", "note": null},
  {"num": 556, "time": "00:31:34,000 --> 00:31:41,000", "arabic": "أَحْلَامُ الْيَوْمِ حَقَائِقُ الْغَدِ يَا فَرَجُ، وَإِنْ بَقِيتَ عَلَى جِدِّكَ وَاجْتِهَادِكَ فَيَوْمًا مَا سَتَنَالُ مَا تَصْبُو إِلَيْهِ إِنْ شَاءَ اللَّهُ", "segs": [{"ar": "أَحْلَامُ الْيَوْمِ حَقَائِقُ الْغَدِ يَا فَرَجُ", "uz": "bugungi tushlar — ertangi haqiqatlar, Faraj"}, {"ar": "وَإِنْ بَقِيتَ عَلَى جِدِّكَ وَاجْتِهَادِكَ فَيَوْمًا مَا سَتَنَالُ مَا تَصْبُو إِلَيْهِ إِنْ شَاءَ اللَّهُ", "uz": "jiddiyligingda davom etsang, bir kun intilgan narsangga Alloh xohlasa yetasan"}], "full_uz": "Bugungi tushlar — ertangi haqiqatlar, Faraj, jiddiyligingda davom etsang, bir kun intilgan narsangga Alloh xohlasa yetasan.", "note": null},
  {"num": 559, "time": "00:31:41,000 --> 00:31:44,000", "arabic": "يَوْمًا مَا", "segs": null, "full_uz": "Bir kun.", "note": null},
  {"num": 560, "time": "00:32:01,000 --> 00:32:05,000", "arabic": "مَا أَجْمَلَ أَنْ يَحْصُلَ الْمَرْءُ عَلَى مَا يَتَمَنَّاهُ فِي أَوَّلِ الْعُمْرِ", "segs": null, "full_uz": "Inson yoshligidayoq orzu qilgan narsasiga erishishi qanday go'zal.", "note": null},
  {"num": 562, "time": "00:32:05,000 --> 00:32:09,000", "arabic": "قَدْ سَمِعْتُ قِصَّتَهَا مِنْ وَلَدِي مَرْوَانَ، إِنَّ قِصَّتَهَا يَنْفَطِرُ لَهَا الْقَلْبُ يَا أُمَّ مَرْوَانَ", "segs": null, "full_uz": "Uning voqeasini o'g'lim Marvondan eshitdim, uning qissasi yurakni ezadi, Umm Marvon.", "note": null},
  {"num": 564, "time": "00:32:09,000 --> 00:32:12,000", "arabic": "كَانَ اللَّهُ فِي عَوْنِهَا", "segs": null, "full_uz": "Alloh unga yordamchi bo'lsin.", "note": null},
  {"num": 565, "time": "00:32:12,000 --> 00:32:15,000", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Sizga salom.", "note": null},
  {"num": 566, "time": "00:32:15,000 --> 00:32:17,000", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 567, "time": "00:32:17,000 --> 00:32:19,000", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 568, "time": "00:32:19,000 --> 00:32:22,000", "arabic": "هَذِهِ الْحَلْوَى صَنَعَتْهَا شَهْنَازُ بِنَفْسِهَا", "segs": null, "full_uz": "Bu shirinlikni Shahnoz o'z qo'li bilan tayyorlagan.", "note": null},
  {"num": 569, "time": "00:32:22,000 --> 00:32:25,000", "arabic": "مَا شَاءَ اللَّهُ، اَلْحُلْوَ يَصْنَعُهُ الْحُلْوُ", "segs": null, "full_uz": "Mashalloh, shirinni shirin odam tayyorlaydi.", "note": null},
  {"num": 570, "time": "00:32:25,000 --> 00:32:26,000", "arabic": "تَفَضَّلِي", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 571, "time": "00:32:26,000 --> 00:32:29,000", "arabic": "سَلِمَتْ يَدَاكِ يَا شَهْنَازُ", "segs": null, "full_uz": "Qo'llaring sog' bo'lsin, Shahnoz.", "note": null},
  {"num": 572, "time": "00:32:29,000 --> 00:32:32,000", "arabic": "لَمْ أَذُقْ مِنْ قَبْلُ حَلْوَى مِثْلَهَا", "segs": null, "full_uz": "Bunga o'xshash shirinlikni ilgari totib ko'rmagandim.", "note": null},
  {"num": 573, "time": "00:32:32,000 --> 00:32:34,000", "arabic": "هَنِيئًا مَرِيئًا يَا خَالَةُ", "segs": null, "full_uz": "Yoqimli, halol bo'lsin, xolajon.", "note": null},
  {"num": 574, "time": "00:32:34,000 --> 00:32:36,000", "arabic": "عَنْ إِذْنِكُمْ", "segs": null, "full_uz": "Ruxsatingiz bilan.", "note": null},
  {"num": 575, "time": "00:32:36,000 --> 00:32:39,000", "arabic": "إِلَى أَيْنَ يَا بُنَيَّتِي؟ أَلَا تَجْلِسِينَ مَعَنَا؟", "segs": null, "full_uz": "Qayerga, qizim? Biz bilan o'tirmaysanmi?", "note": null},
  {"num": 577, "time": "00:32:39,000 --> 00:32:43,000", "arabic": "وَدِدْتُ ذَلِكَ، لَكِنَّنِي لَمَّا أَنْتَهِ بَعْدُ مِنْ بَعْضِ أَعْمَالِ الْبَيْتِ", "segs": null, "full_uz": "Xohlar edim, lekin uy ishlarining ba'zisini hali tugatmadim.", "note": null},
  {"num": 580, "time": "00:32:43,000 --> 00:32:46,000", "arabic": "بَارَكَ اللَّهُ فِيكِ، اِذْهَبِي إِذَنْ لِشَأْنِكِ، اِذْهَبِي يَا بُنَيَّتِي", "segs": null, "full_uz": "Alloh senga baraka bersin, unda o'z ishingga bor, bor, qizim.", "note": null},
  {"num": 583, "time": "00:33:01,000 --> 00:33:05,000", "arabic": "تَبَارَكَ الْوَهَّابُ الْخَلَّاقُ، مَا أَشَدَّ جَمَالَهَا وَمَا أَلْطَفَ حَيَاءَهَا", "segs": null, "full_uz": "Barakali bo'lsin Vahhob, Xalloq — u naqadar go'zal va uning uyati naqadar nozik.", "note": null},
  {"num": 585, "time": "00:33:05,000 --> 00:33:08,000", "arabic": "بَارَكَ اللَّهُ بِكِ يَا أُمَّ مَرْوَانَ", "segs": null, "full_uz": "Alloh senga baraka bersin, Umm Marvon.", "note": null},
  {"num": 586, "time": "00:33:31,000 --> 00:33:35,000", "arabic": "فَوْزُ، فَوْزُ، اسْتَيْقِظِي", "segs": null, "full_uz": "Favz, Favz, uyg'on.", "note": null},
  {"num": 588, "time": "00:33:35,000 --> 00:33:38,000", "arabic": "اسْتَيْقِظِي بِسُرْعَةٍ أَرْجُوكِ", "segs": null, "full_uz": "Tezroq uyg'on, iltimos.", "note": null},
  {"num": 590, "time": "00:33:38,000 --> 00:33:40,000", "arabic": "فَوْزُ", "segs": null, "full_uz": "Favz!", "note": null},
  {"num": 591, "time": "00:33:40,000 --> 00:33:42,000", "arabic": "مَنْ؟ مَنْ هُنَا؟", "segs": null, "full_uz": "Kim? Bu yerda kim bor?", "note": null},
  {"num": 592, "time": "00:33:42,000 --> 00:33:47,000", "arabic": "أَنَا حَنْظَلَةُ، حَنْظَلَةُ زَوْجُ زُمُرُّدَةَ، لَا تَخَافِي، تَعَالَيْ", "segs": null, "full_uz": "Men Hanzalaman, Zumurradning eri Hanzala. Qo'rqma, bu yoqqa kel.", "note": null},
  {"num": 594, "time": "00:33:47,000 --> 00:33:53,000", "arabic": "اِذْهَبْ، اِذْهَبْ مِنْ هُنَا وَإِلَّا مَلَأْتُ الدُّنْيَا صُرَاخًا يَفْضَحُ أَمْرَكَ يَا زَوْجَ زُمُرُّدَةَ", "segs": null, "full_uz": "Ket, bu yerdan ket, aks holda ishingni fosh qiladigan baqiriq bilan dunyoni to'ldiraman, Zumurradning eri.", "note": null},
  {"num": 597, "time": "00:33:53,000 --> 00:33:58,000", "arabic": "إِلَى أَيْنَ ذَهَبَ عَقْلُكِ يَا فَوْزُ؟ لَقَدْ أَحْضَرْتُ لَكِ طَعَامًا", "segs": null, "full_uz": "Aqling qayerga ketdi, Favz? Senga ovqat olib keldim.", "note": null},
  {"num": 598, "time": "00:33:58,000 --> 00:34:02,000", "arabic": "وَمَا زِلْتَ تُلِحُّ بِطَعَامِكَ؟ أَقْسِمُ بِاللَّهِ لَا أُرِيدُ شَيْئًا", "segs": null, "full_uz": "Hali ham ovqating bilan qistayapsanmi? Allohga qasamki, hech narsa xohlamayman.", "note": null},
  {"num": 600, "time": "00:34:02,000 --> 00:34:08,000", "arabic": "خُذِيهِ بِسُرْعَةٍ قَبْلَ أَنْ تَسْتَيْقِظَ زَوْجَتِي فَيَخِرَّ هَذَا السَّقْفُ عَلَى رَأْسِي", "segs": null, "full_uz": "Xotinim uyg'onmasdan tezroq ol, bo'lmasa bu tom boshimga qulaydi.", "note": "«يَخِرُّ السَّقْفُ عَلَى رَأْسِهِ» — «tom boshiga qulaydi», ya'ni katta muammoga duch kelmoq ma'nosidagi majoziy ibora."},
  {"num": 602, "time": "00:34:08,000 --> 00:34:13,000", "arabic": "وَلَكِنْ حَاوِلِي أَنْ تُخْفِي آثَارَ الطَّعَامِ بَعْدَ أَنْ تَنْتَهِي، فَإِنْ وَجَدَتْهُ زَوْجَتِي سَتَكُونُ تِلْكَ قَاصِمَةَ ظَهْرِي وَقَاطِعَةَ رَأْسِي", "segs": null, "full_uz": "Lekin tugatgach, ovqat izlarini yashirishga harakat qil, agar xotinim topib qolsa, bu mening belimni sindirib, boshimni kesadi.", "note": null},
  {"num": 604, "time": "00:34:13,000 --> 00:34:17,000", "arabic": "حَسَنًا سَأَفْعَلُ، شُكْرًا لَكَ عَلَى أَيِّ حَالٍ", "segs": null, "full_uz": "Xo'p, shunday qilaman, baribir rahmat senga.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}